/* Daily Plate v2.5 consolidated application loader.
   Legacy feature layers execute in their established classic-script order while
   the deployed PWA uses one permanent physical app.js file. */
(function(){
  const layers = [{"name": "app.js", "code": "/* ===================== Daily Plate — app logic ===================== */\n\nconst MEALS = [\n  {key:'breakfast', name:'Breakfast', icon:'🥐'},\n  {key:'lunch', name:'Lunch', icon:'🥗'},\n  {key:'dinner', name:'Dinner', icon:'🍲'},\n  {key:'snacks', name:'Snacks', icon:'🍎'},\n];\n\nlet STATE = {\n  profile: null,\n  customIngredients: [],\n  deletedBuiltins: [],\n  logs: {}, // dateKey -> { breakfast:[{id,name,grams,cal,p,c,f,sugar}], lunch:[...], ... }\n};\n\nlet activeMealKey = null;\nlet activeIngredientForQty = null;\nlet activeEditingIngredientId = null;\nlet viewingLogDate = null;\nlet logEditMode = false;\nlet editingLogDate = null; // null = today; set = past day being edited\n\n/* ---------- persistence ---------- */\nfunction save(){ localStorage.setItem('dp_state', JSON.stringify(STATE)); }\nfunction load(){\n  const raw = localStorage.getItem('dp_state');\n  if(raw){ STATE = JSON.parse(raw); if(!STATE.customIngredients) STATE.customIngredients=[]; if(!STATE.deletedBuiltins) STATE.deletedBuiltins=[]; if(!STATE.logs) STATE.logs={}; }\n}\n\n/* ---------- date helpers (this is what makes the daily log \"close\" at midnight) ---------- */\nfunction todayKey(){\n  const d = new Date();\n  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');\n}\nfunction keyToDate(k){ const [y,m,d]=k.split('-').map(Number); return new Date(y,m-1,d); }\nfunction fmtDateLong(k){\n  return keyToDate(k).toLocaleDateString(undefined,{weekday:'long', month:'long', day:'numeric'});\n}\nfunction getDayLog(key){\n  if(!STATE.logs[key]) STATE.logs[key] = {breakfast:[],lunch:[],dinner:[],snacks:[]};\n  return STATE.logs[key];\n}\n\n/* ---------- ingredient library (built-in + custom, minus deletions) ---------- */\nfunction allIngredients(){\n  const builtins = INGREDIENTS\n    .map((ing,i)=>({...ing, id:'b'+i}))\n    .filter(ing=>!STATE.deletedBuiltins.includes(ing.id));\n  return [...STATE.customIngredients, ...builtins];\n}\nfunction findIngredient(id){ return allIngredients().find(i=>i.id===id); }\n\n/* ---------- nutrition math ---------- */\nfunction calcBMR(p){\n  const base = 10*p.weight + 6.25*p.height - 5*p.age;\n  return p.sex==='male' ? base+5 : base-161;\n}\nfunction calcTDEE(p){ return calcBMR(p)*parseFloat(p.activity); }\nfunction calcCalorieTarget(p){\n  if(p.customCalTarget) return p.customCalTarget;\n  const tdee = calcTDEE(p);\n  if(p.goal==='lose') return Math.round(tdee-500);\n  if(p.goal==='gain') return Math.round(tdee+300);\n  return Math.round(tdee);\n}\nfunction calcProteinTarget(p){\n  if(p.proteinTarget) return p.proteinTarget;\n  return Math.round(p.weight*1.6);\n}\nfunction calcBMI(p){ return p.weight/((p.height/100)**2); }\n\n/* ---------- navigation ---------- */\nfunction goTo(screenId){\n  document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));\n  document.getElementById(screenId).classList.add('active');\n}\nfunction switchTab(screenId){\n  goTo(screenId);\n  document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active', t.dataset.tab===screenId));\n  if(screenId==='screen-today') renderToday();\n  if(screenId==='screen-log') renderLog();\n  if(screenId==='screen-ingredients') renderIngredientLibrary();\n  if(screenId==='screen-profile') renderProfileScreen();\n}\nfunction openSheet(id){ document.getElementById(id).classList.add('active'); }\nfunction closeSheet(id){ document.getElementById(id).classList.remove('active'); }\nfunction toast(msg){\n  const t = document.getElementById('toast');\n  t.textContent = msg; t.classList.add('show');\n  setTimeout(()=>t.classList.remove('show'), 1800);\n}\n\n/* ---------- onboarding ---------- */\nfunction completeSetup(){\n  const name = document.getElementById('su-name').value.trim() || 'Friend';\n  const age = parseFloat(document.getElementById('su-age').value);\n  const sex = document.getElementById('su-sex').value;\n  const height = parseFloat(document.getElementById('su-height').value);\n  const weight = parseFloat(document.getElementById('su-weight').value);\n  const activity = document.getElementById('su-activity').value;\n  const goal = document.getElementById('su-goal').value;\n  const proteinInput = parseFloat(document.getElementById('su-protein').value);\n\n  if(!age||!height||!weight){ toast('Please fill in age, height and weight'); return; }\n\n  STATE.profile = {\n    name, age, sex, height, weight, activity, goal,\n    proteinTarget: proteinInput || null,\n    customCalTarget: null,\n  };\n  save();\n  initMainApp();\n}\n\n/* ---------- TODAY screen ---------- */\nfunction renderToday(){\n  if(!STATE.profile) return;\n  const key = todayKey();\n  const log = getDayLog(key);\n  document.getElementById('today-date').textContent = fmtDateLong(key).toUpperCase();\n  document.getElementById('today-greeting').textContent = 'Hello, '+STATE.profile.name;\n\n  let totals = {cal:0,p:0,c:0,f:0};\n  MEALS.forEach(m=>{\n    (log[m.key]||[]).forEach(e=>{ totals.cal+=e.cal; totals.p+=e.p; totals.c+=e.c; totals.f+=e.f; });\n  });\n\n  const calTarget = calcCalorieTarget(STATE.profile);\n  const proteinTarget = calcProteinTarget(STATE.profile);\n  const carbTarget = Math.round((calTarget*0.45)/4);\n  const fatTarget = Math.round((calTarget*0.27)/9);\n\n  const remaining = Math.max(calTarget-totals.cal, 0);\n  document.getElementById('cal-eaten-sub').textContent = Math.round(totals.cal);\n  document.getElementById('cal-remaining-sub').textContent = Math.round(remaining) + ' remaining';\n  document.getElementById('cal-target-sub').textContent = `of ${calTarget} target`;\n\n  const circumference = 603;\n  const pct = Math.min(totals.cal/calTarget,1);\n  document.getElementById('ring-progress').setAttribute('stroke-dashoffset', circumference*(1-pct));\n  const ring = document.getElementById('ring-progress');\n  ring.setAttribute('stroke', totals.cal>calTarget ? '#E8643A' : '#E8643A');\n\n  setPill('protein', totals.p, proteinTarget);\n  setPill('carb', totals.c, carbTarget);\n  setPill('fat', totals.f, fatTarget);\n\n  renderMealsContainer(log, key);\n}\nfunction setPill(name, val, target){\n  document.getElementById('pv-'+name).textContent = Math.round(val)+'g';\n  document.getElementById('pb-'+name).style.width = Math.min((val/target)*100,100)+'%';\n  document.getElementById('pt-'+name).textContent = 'of '+target+'g';\n}\n\nfunction renderMealsContainer(log, dayKey, editable=true){\n  const isToday = dayKey === todayKey();\n  // Today screen always uses meals-container; log screen uses log-day-detail\n  const container = document.getElementById(isToday ? 'meals-container' : 'log-day-detail');\n  container.innerHTML = '';\n  MEALS.forEach(m=>{\n    const entries = log[m.key]||[];\n    const mealCal = entries.reduce((a,e)=>a+e.cal,0);\n    const card = document.createElement('div');\n    card.className = 'card meal-card';\n    card.innerHTML = `\n      <div class=\"meal-head\">\n        <div class=\"left\">\n          <div class=\"meal-icon\">${m.icon}</div>\n          <div><div class=\"meal-name\">${m.name}</div><div class=\"meal-cals\">${Math.round(mealCal)} kcal</div></div>\n        </div>\n        ${editable ? `<button class=\"add-btn\" onclick=\"openAddSheet('${m.key}','${isToday?'':dayKey}')\">+</button>` : ''}\n      </div>\n      <div class=\"entry-list\">\n        ${entries.length===0 ? `<div class=\"empty-hint\">${editable?'Tap + to add food':'Nothing logged'}</div>` : entries.map((e,idx)=>`\n          <div class=\"entry\">\n            <div>\n              <div class=\"ename\">${e.name}</div>\n              <div class=\"emeta\">${e.grams}${e.unit||'g'} · P${Math.round(e.p)} C${Math.round(e.c)} F${Math.round(e.f)}</div>\n            </div>\n            <div class=\"eright\">\n              <div class=\"ecal\">${Math.round(e.cal)}</div>\n              ${editable ? `<button class=\"edel\" onclick=\"deleteEntry('${dayKey}','${m.key}',${idx})\">✕</button>` : ''}\n            </div>\n          </div>\n        `).join('')}\n      </div>\n    `;\n    container.appendChild(card);\n  });\n}\n\nfunction deleteEntry(dayKey, mealKey, idx){\n  STATE.logs[dayKey][mealKey].splice(idx,1);\n  save();\n  if(dayKey===todayKey()) renderToday(); else renderLogDayDetail(dayKey);\n}\n\n/* ---------- Add-to-meal flow ---------- */\n\n// Returns top-N ingredient names for a given meal slot, ranked by how often logged\nfunction getFrequentItems(mealKey, n=5){\n  const counts = {};\n  Object.values(STATE.logs).forEach(dayLog => {\n    (dayLog[mealKey] || []).forEach(entry => {\n      // Normalise: strip \"×N\" suffix added for countable items so they group correctly\n      const base = entry.name.replace(/\\s×\\d+(\\.\\d+)?$/, '').trim();\n      counts[base] = (counts[base] || 0) + 1;\n    });\n  });\n  return Object.entries(counts)\n    .sort((a,b) => b[1]-a[1])\n    .slice(0, n)\n    .map(([name, count]) => ({ name, count }));\n}\n\nfunction openAddSheet(mealKey, targetDate){\n  activeMealKey = mealKey;\n  editingLogDate = targetDate || null;\n  const meal = MEALS.find(m=>m.key===mealKey);\n  document.getElementById('add-sheet-title').textContent = 'Add to '+meal.name;\n  document.getElementById('add-search').value='';\n\n  // Render frequent items for this specific meal slot\n  const freq = getFrequentItems(mealKey, 5);\n  const freqSection = document.getElementById('freq-section');\n  const freqList = document.getElementById('freq-list');\n  const freqDivider = document.getElementById('freq-divider');\n\n  if(freq.length > 0){\n    freqSection.style.display = '';\n    freqList.innerHTML = freq.map(({name, count}) => {\n      // Try to find a matching ingredient for calorie display\n      const ing = allIngredients().find(i => i.name === name);\n      const calHint = ing ? `${ing.cal} kcal/100g` : '';\n      return `\n        <div class=\"freq-chip\" onclick=\"openQtySheetByName('${name.replace(/'/g,\"\\\\'\")}')\">\n          <div class=\"freq-name\">${name}</div>\n          <div class=\"freq-meta\">${calHint}<span class=\"freq-count\">${count}×</span></div>\n        </div>\n      `;\n    }).join('');\n    freqDivider.style.display = '';\n  } else {\n    freqSection.style.display = 'none';\n    freqDivider.style.display = 'none';\n  }\n\n  renderAddSearch();\n  openSheet('sheet-add');\n}\n\nfunction renderAddSearch(){\n  const q = document.getElementById('add-search').value.toLowerCase();\n  const freqSection = document.getElementById('freq-section');\n  const freqDivider = document.getElementById('freq-divider');\n\n  // Hide frequent section while actively searching\n  if(q){\n    freqSection.style.display = 'none';\n    freqDivider.style.display = 'none';\n  } else {\n    const freq = getFrequentItems(activeMealKey, 5);\n    freqSection.style.display = freq.length ? '' : 'none';\n    freqDivider.style.display = freq.length ? '' : 'none';\n  }\n\n  const list = allIngredients().filter(i=>i.name.toLowerCase().includes(q)).slice(0,60);\n  const el = document.getElementById('add-search-results');\n  el.innerHTML = list.map(i=>`\n    <div class=\"ing-row\" onclick=\"openQtySheet('${i.id}')\">\n      <div><div class=\"iname\">${i.name}</div><div class=\"icat\">${i.cat}</div></div>\n      <div class=\"ical\">${i.cal} kcal</div>\n    </div>\n  `).join('') || `<div class=\"empty-hint\">No matches — add it in the Ingredients tab</div>`;\n}\n\n// Open qty sheet by ingredient name (used by frequent chips)\nfunction openQtySheetByName(name){\n  const ing = allIngredients().find(i => i.name === name);\n  if(ing){ openQtySheet(ing.id); return; }\n  // If ingredient was deleted or custom, fall back to showing grams mode with a placeholder\n  toast('Ingredient not found in database');\n}\nlet qtyMode = 'count'; // 'count' or 'grams'\nlet qtyCount = 1;\n\nfunction openQtySheet(ingId){\n  activeIngredientForQty = ingId;\n  const ing = findIngredient(ingId);\n  document.getElementById('qty-ing-name').textContent = ing.name;\n  const unit = ing.isLiquid ? 'ml' : 'g';\n\n  if(ing.uw && !ing.isLiquid){\n    // Countable solid ingredient — start in count mode\n    qtyMode = 'count';\n    qtyCount = 1;\n    document.getElementById('qty-count-mode').style.display = '';\n    document.getElementById('qty-gram-mode').style.display = 'none';\n    document.getElementById('qty-count-unit').textContent = ing.unit;\n    document.getElementById('qty-count-grams-hint').textContent = '= '+Math.round(ing.uw)+'g';\n    document.getElementById('qty-gram-switch-wrap').innerHTML =\n      `<button class=\"switch-mode-btn\" onclick=\"switchQtyMode('grams')\">Enter grams instead →</button>`;\n  } else {\n    // Weight/volume-based — show counter with correct unit\n    qtyMode = 'grams';\n    document.getElementById('qty-count-mode').style.display = 'none';\n    document.getElementById('qty-gram-mode').style.display = '';\n    document.getElementById('qty-gram-switch-wrap').innerHTML = '';\n    document.getElementById('qty-gram-unit').textContent = unit;\n    const defaultAmt = ing.defaultServing || (ing.isLiquid ? 240 : 100);\n    document.getElementById('qty-grams').value = defaultAmt;\n  }\n  updateQtyPreview();\n  closeSheet('sheet-add');\n  openSheet('sheet-qty');\n}\n\nfunction switchQtyMode(mode){\n  const ing = findIngredient(activeIngredientForQty);\n  const unit = ing.isLiquid ? 'ml' : 'g';\n  qtyMode = mode;\n  if(mode === 'grams'){\n    document.getElementById('qty-count-mode').style.display = 'none';\n    document.getElementById('qty-gram-mode').style.display = '';\n    const val = ing.uw ? Math.round(qtyCount * ing.uw) : (ing.defaultServing || (ing.isLiquid ? 240 : 100));\n    document.getElementById('qty-grams').value = val;\n    document.getElementById('qty-gram-unit').textContent = unit;\n    document.getElementById('qty-gram-switch-wrap').innerHTML =\n      ing.uw ? `<button class=\"switch-mode-btn\" onclick=\"switchQtyMode('count')\">← Back to ${ing.unit} count</button>` : '';\n  } else {\n    document.getElementById('qty-count-mode').style.display = '';\n    document.getElementById('qty-gram-mode').style.display = 'none';\n  }\n  updateQtyPreview();\n}\n\nfunction changeCount(delta){\n  qtyCount = Math.max(1, qtyCount + delta);\n  document.getElementById('qty-count-num').textContent = qtyCount;\n  updateQtyPreview();\n}\n\nfunction changeGrams(delta){\n  const ing = findIngredient(activeIngredientForQty);\n  const step = ing && ing.isLiquid ? 50 : 25;\n  const input = document.getElementById('qty-grams');\n  const cur = parseFloat(input.value) || 0;\n  const minVal = ing && ing.isLiquid ? 50 : 25;\n  input.value = Math.max(minVal, cur + (delta * step));\n  updateQtyPreview();\n}\n\nfunction updateQtyPreview(){\n  const ing = findIngredient(activeIngredientForQty);\n  let g;\n  if(qtyMode === 'count' && ing.uw){\n    g = qtyCount * ing.uw;\n    document.getElementById('qty-count-grams-hint').textContent = '= '+Math.round(g)+'g';\n  } else {\n    g = parseFloat(document.getElementById('qty-grams').value)||0;\n  }\n  const f = g/100;\n  // For liquids: nutritional math is identical (100ml ≈ 100g for all tracked beverages)\n  document.getElementById('qp-cal').textContent = Math.round(ing.cal*f);\n  document.getElementById('qp-protein').textContent = Math.round(ing.p*f)+'g';\n  document.getElementById('qp-carb').textContent = Math.round(ing.c*f)+'g';\n  document.getElementById('qp-fat').textContent = Math.round(ing.f*f)+'g';\n}\n\nfunction confirmAddEntry(){\n  const ing = findIngredient(activeIngredientForQty);\n  let g;\n  if(qtyMode === 'count' && ing.uw){\n    g = qtyCount * ing.uw;\n  } else {\n    g = parseFloat(document.getElementById('qty-grams').value)||0;\n  }\n  if(g<=0){ toast('Enter a valid amount'); return; }\n  const f = g/100;\n  const unit = ing.isLiquid ? 'ml' : 'g';\n  let label = ing.name;\n  if(qtyMode === 'count' && ing.uw){ label = ing.name + ' ×'+ qtyCount; }\n  const entry = {\n    name: label, grams: Math.round(g), unit,\n    cal: ing.cal*f, p: ing.p*f, c: ing.c*f, f: ing.f*f, sugar:(ing.sugar||0)*f\n  };\n  const key = editingLogDate || todayKey();\n  getDayLog(key)[activeMealKey].push(entry);\n  save();\n  closeSheet('sheet-qty');\n  toast('Added to '+MEALS.find(m=>m.key===activeMealKey).name);\n  if(editingLogDate){ renderLogDayDetail(editingLogDate); } else { renderToday(); }\n}\n\n/* ---------- LOG / history screen ---------- */\nfunction tomorrowKey(){\n  const d = new Date(); d.setDate(d.getDate()+1);\n  return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');\n}\nfunction isFutureDay(k){ return k > todayKey(); }\nfunction isPastDay(k){ return k < todayKey(); }\n\nfunction renderLog(){\n  const strip = document.getElementById('day-strip');\n  strip.innerHTML='';\n  const today = new Date();\n  const keys = [];\n  // 13 days back → today → tomorrow (+1 day ahead only)\n  for(let i=13;i>=-1;i--){\n    const d = new Date(today); d.setDate(d.getDate()-i);\n    const k = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');\n    keys.push(k);\n  }\n  if(!viewingLogDate) viewingLogDate = todayKey();\n  // If somehow beyond 1-day future, reset to today\n  if(viewingLogDate > tomorrowKey()) viewingLogDate = todayKey();\n\n  keys.forEach(k=>{\n    const d = keyToDate(k);\n    const isToday = k === todayKey();\n    const isTomorrow = k === tomorrowKey();\n    let cls = 'day-chip';\n    if(k === viewingLogDate) cls += ' active';\n    if(isToday) cls += ' today';\n    if(isTomorrow) cls += ' tomorrow-chip';\n    const chip = document.createElement('div');\n    chip.className = cls;\n    chip.innerHTML = `<div class=\"d\">${d.getDate()}</div><div>${isTomorrow ? 'tmrw' : d.toLocaleDateString(undefined,{month:'short'})}</div>`;\n    chip.onclick = ()=>{\n      viewingLogDate = k;\n      // Auto-enter edit mode for tomorrow so user can plan ahead immediately\n      logEditMode = isFutureDay(k);\n      renderLog();\n      // Scroll chip into view\n      chip.scrollIntoView({behavior:'smooth', block:'nearest', inline:'center'});\n    };\n    strip.appendChild(chip);\n  });\n\n  // Scroll to end (today/tomorrow) on first render\n  strip.scrollLeft = strip.scrollWidth;\n\n  const isToday = viewingLogDate === todayKey();\n  const isTomorrow = viewingLogDate === tomorrowKey();\n  const isPast = isPastDay(viewingLogDate);\n\n  let dayLabel = fmtDateLong(viewingLogDate);\n  if(isToday) dayLabel += ' (today)';\n  else if(isTomorrow) dayLabel += ' (tomorrow)';\n  else dayLabel += ' (closed)';\n  document.getElementById('log-day-title').textContent = dayLabel;\n\n  // Edit button: hide for today (always editable there), show for past and tomorrow\n  const editBtn = document.getElementById('log-edit-btn');\n  editBtn.style.display = isToday ? 'none' : '';\n  editBtn.classList.toggle('active', logEditMode);\n\n  // For tomorrow: label it \"Plan ahead\" instead of \"Edit day\"\n  if(isTomorrow){\n    editBtn.innerHTML = logEditMode\n      ? `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" width=\"14\" height=\"14\"><polyline points=\"20 6 9 17 4 12\"/></svg> Done`\n      : `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" width=\"14\" height=\"14\"><path d=\"M12 5v14M5 12h14\"/></svg> Plan ahead`;\n  } else {\n    editBtn.innerHTML = logEditMode\n      ? `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" width=\"14\" height=\"14\"><polyline points=\"20 6 9 17 4 12\"/></svg> Done editing`\n      : `<svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" width=\"14\" height=\"14\"><path d=\"M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7\"/><path d=\"M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z\"/></svg> Edit day`;\n  }\n\n  renderLogDayDetail(viewingLogDate);\n  renderWeekBar();\n}\n\nfunction toggleLogEdit(){\n  logEditMode = !logEditMode;\n  renderLog();\n}\nfunction renderLogDayDetail(dayKey){\n  const log = getDayLog(dayKey);\n  // Today and tomorrow are always editable in log view; past days need edit mode\n  const editable = dayKey >= todayKey() ? true : logEditMode;\n  renderMealsContainer(log, dayKey, editable);\n}\nfunction renderWeekBar(){\n  const wb = document.getElementById('weekbar');\n  wb.innerHTML='';\n  const today = new Date();\n  const target = STATE.profile ? calcCalorieTarget(STATE.profile) : 2000;\n  let maxCal = target;\n  const days = [];\n  for(let i=6;i>=0;i--){\n    const d = new Date(today); d.setDate(d.getDate()-i);\n    const k = d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');\n    const log = STATE.logs[k] || {breakfast:[],lunch:[],dinner:[],snacks:[]};\n    let cal=0; MEALS.forEach(m=>(log[m.key]||[]).forEach(e=>cal+=e.cal));\n    days.push({k,d,cal});\n    if(cal>maxCal) maxCal=cal;\n  }\n  days.forEach(day=>{\n    const isToday = day.k===todayKey();\n    const hasCal = day.cal > 0;\n    const h = hasCal ? Math.max((day.cal/maxCal)*76, 6) : 3;\n    const overTarget = day.cal > target;\n    const calLabel = hasCal ? (day.cal >= 1000 ? (day.cal/1000).toFixed(1)+'k' : Math.round(day.cal)+'') : '';\n    const col = document.createElement('div');\n    col.className = 'col';\n    col.innerHTML = `\n      <div class=\"bar-cal-label\" style=\"opacity:${hasCal?1:0}\">${calLabel}</div>\n      <div class=\"bar ${overTarget?'over-target':''}\" style=\"height:${h}px;opacity:${isToday?1:0.6}\"></div>\n      <div class=\"lbl ${isToday?'lbl-today':''}\">${day.d.toLocaleDateString(undefined,{weekday:'narrow'})}</div>\n    `;\n    col.onclick = ()=>{ viewingLogDate=day.k; logEditMode=false; switchTab('screen-log'); };\n    wb.appendChild(col);\n  });\n}\n\n/* ---------- Ingredients screen ---------- */\nfunction renderIngredientLibrary(){\n  const q = (document.getElementById('ing-search').value||'').toLowerCase();\n  const list = allIngredients().filter(i=>i.name.toLowerCase().includes(q))\n    .sort((a,b)=>a.name.localeCompare(b.name)).slice(0,200);\n  const el = document.getElementById('ingredient-library');\n  el.innerHTML = list.map(i=>`\n    <div class=\"ing-row\" onclick=\"openIngredientEditor('${i.id}')\">\n      <div><div class=\"iname\">${i.name}</div><div class=\"icat\">${i.cat}${i.id.startsWith('custom')?' · custom':''}</div></div>\n      <div class=\"ical\">${i.cal} kcal</div>\n    </div>\n  `).join('');\n}\nlet isLiquidToggleOn = false;\n\nfunction toggleIsLiquid(){\n  isLiquidToggleOn = !isLiquidToggleOn;\n  const el = document.getElementById('ie-liquid-toggle');\n  el.classList.toggle('on', isLiquidToggleOn);\n  document.getElementById('ie-serving-unit-hint').textContent =\n    isLiquidToggleOn ? 'Default ml pre-filled when adding to a meal' : 'Pre-fills when you add this to a meal';\n}\n\nfunction openIngredientEditor(id){\n  activeEditingIngredientId = id;\n  const isNew = !id;\n  document.getElementById('ie-title').textContent = isNew? 'New ingredient' : 'Edit ingredient';\n  document.getElementById('ie-delete-btn').style.display = isNew? 'none':'inline-flex';\n  const ing = isNew ? {name:'',cat:'',cal:'',p:'',c:'',f:'',sugar:'',fiber:'',sodium:'',defaultServing:100,isLiquid:false} : findIngredient(id);\n  document.getElementById('ie-name').value = ing.name;\n  document.getElementById('ie-cat').value = ing.cat;\n  document.getElementById('ie-cal').value = ing.cal;\n  document.getElementById('ie-protein').value = ing.p;\n  document.getElementById('ie-carb').value = ing.c;\n  document.getElementById('ie-fat').value = ing.f;\n  document.getElementById('ie-sugar').value = ing.sugar;\n  document.getElementById('ie-fiber').value = ing.fiber;\n  document.getElementById('ie-sodium').value = ing.sodium;\n  document.getElementById('ie-default-serving').value = ing.defaultServing || (ing.uw ? Math.round(ing.uw) : (ing.isLiquid ? 240 : 100));\n  isLiquidToggleOn = !!(ing.isLiquid);\n  document.getElementById('ie-liquid-toggle').classList.toggle('on', isLiquidToggleOn);\n  document.getElementById('ie-serving-unit-hint').textContent =\n    isLiquidToggleOn ? 'Default ml pre-filled when adding to a meal' : 'Pre-fills when you add this to a meal';\n  openSheet('sheet-ing-edit');\n}\nfunction saveIngredientEditor(){\n  const name = document.getElementById('ie-name').value.trim();\n  if(!name){ toast('Name is required'); return; }\n  const data = {\n    name,\n    cat: document.getElementById('ie-cat').value.trim()||'Custom',\n    cal: parseFloat(document.getElementById('ie-cal').value)||0,\n    p: parseFloat(document.getElementById('ie-protein').value)||0,\n    c: parseFloat(document.getElementById('ie-carb').value)||0,\n    f: parseFloat(document.getElementById('ie-fat').value)||0,\n    sugar: parseFloat(document.getElementById('ie-sugar').value)||0,\n    fiber: parseFloat(document.getElementById('ie-fiber').value)||0,\n    sodium: parseFloat(document.getElementById('ie-sodium').value)||0,\n    defaultServing: parseFloat(document.getElementById('ie-default-serving').value)||100,\n    isLiquid: isLiquidToggleOn,\n  };\n  if(activeEditingIngredientId && activeEditingIngredientId.startsWith('custom')){\n    const idx = STATE.customIngredients.findIndex(i=>i.id===activeEditingIngredientId);\n    STATE.customIngredients[idx] = {...data, id:activeEditingIngredientId};\n  } else if(activeEditingIngredientId && activeEditingIngredientId.startsWith('b')){\n    // editing a built-in: soft-delete the built-in, add an edited custom copy\n    STATE.deletedBuiltins.push(activeEditingIngredientId);\n    STATE.customIngredients.push({...data, id:'custom'+Date.now()});\n  } else {\n    STATE.customIngredients.push({...data, id:'custom'+Date.now()});\n  }\n  save();\n  closeSheet('sheet-ing-edit');\n  toast('Ingredient saved');\n  renderIngredientLibrary();\n}\nfunction deleteIngredientEditor(){\n  if(!activeEditingIngredientId) return;\n  if(activeEditingIngredientId.startsWith('custom')){\n    STATE.customIngredients = STATE.customIngredients.filter(i=>i.id!==activeEditingIngredientId);\n  } else {\n    STATE.deletedBuiltins.push(activeEditingIngredientId);\n  }\n  save();\n  closeSheet('sheet-ing-edit');\n  toast('Ingredient deleted');\n  renderIngredientLibrary();\n}\n\n/* ---------- Profile screen ---------- */\nfunction renderProfileScreen(){\n  const p = STATE.profile;\n  document.getElementById('profile-name').textContent = p.name+\"'s profile\";\n  document.getElementById('pf-bmi').textContent = calcBMI(p).toFixed(1);\n  document.getElementById('pf-bmr').textContent = Math.round(calcBMR(p));\n  document.getElementById('pf-tdee').textContent = Math.round(calcTDEE(p));\n  document.getElementById('pf-target').textContent = calcCalorieTarget(p);\n\n  document.getElementById('pf-edit-name').value = p.name;\n  document.getElementById('pf-edit-age').value = p.age;\n  document.getElementById('pf-edit-sex').value = p.sex;\n  document.getElementById('pf-edit-height').value = p.height;\n  document.getElementById('pf-edit-weight').value = p.weight;\n  document.getElementById('pf-edit-activity').value = p.activity;\n  document.getElementById('pf-edit-goal').value = p.goal;\n  document.getElementById('pf-edit-caltarget').value = p.customCalTarget || '';\n  document.getElementById('pf-edit-protein').value = p.proteinTarget || '';\n}\nfunction saveProfileEdits(){\n  STATE.profile = {\n    name: document.getElementById('pf-edit-name').value.trim()||'Friend',\n    age: parseFloat(document.getElementById('pf-edit-age').value),\n    sex: document.getElementById('pf-edit-sex').value,\n    height: parseFloat(document.getElementById('pf-edit-height').value),\n    weight: parseFloat(document.getElementById('pf-edit-weight').value),\n    activity: document.getElementById('pf-edit-activity').value,\n    goal: document.getElementById('pf-edit-goal').value,\n    customCalTarget: parseFloat(document.getElementById('pf-edit-caltarget').value)||null,\n    proteinTarget: parseFloat(document.getElementById('pf-edit-protein').value)||null,\n  };\n  save();\n  toast('Profile updated');\n  renderProfileScreen();\n}\nfunction exportData(){\n  const blob = new Blob([JSON.stringify(STATE,null,2)], {type:'application/json'});\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href=url; a.download='daily-plate-backup.json'; a.click();\n  URL.revokeObjectURL(url);\n}\n\nfunction importData(event){\n  const file = event.target.files[0];\n  if(!file){ return; }\n  const reader = new FileReader();\n  reader.onload = (e) => {\n    try {\n      const imported = JSON.parse(e.target.result);\n      // Validate it looks like a Daily Plate backup\n      if(!imported.profile && !imported.logs){\n        toast('Invalid backup file'); return;\n      }\n      const hasExistingLogs = Object.keys(STATE.logs||{}).length > 0;\n      const hasExistingCustom = (STATE.customIngredients||[]).length > 0;\n      const warnMsg = (hasExistingLogs || hasExistingCustom)\n        ? 'This will replace your current logs and ingredients. Are you sure?'\n        : 'Import this backup? Your profile and data will be restored.';\n\n      if(!confirm(warnMsg)){ event.target.value=''; return; }\n\n      // Restore: merge intelligently\n      if(imported.profile) STATE.profile = imported.profile;\n      if(imported.logs) STATE.logs = imported.logs;\n      if(imported.customIngredients) STATE.customIngredients = imported.customIngredients;\n      if(imported.deletedBuiltins) STATE.deletedBuiltins = imported.deletedBuiltins;\n\n      save();\n      event.target.value = '';\n      toast('✓ Data imported successfully');\n      renderProfileScreen();\n      renderToday();\n    } catch(err){\n      toast('Could not read file — check it is a valid backup');\n      event.target.value = '';\n    }\n  };\n  reader.readAsText(file);\n}\n\n/* ---------- clock / midnight rollover watcher ---------- */\nlet lastSeenDay = todayKey();\nfunction tickClock(){\n  const now = new Date();\n  document.getElementById('today-clock').textContent = now.toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});\n  const k = todayKey();\n  if(k!==lastSeenDay){\n    lastSeenDay = k;\n    toast(\"New day — yesterday's log is closed\");\n    if(document.getElementById('screen-today').classList.contains('active')) renderToday();\n  }\n}\n\n/* ---------- init ---------- */\nfunction initMainApp(){\n  document.getElementById('tabbar').style.display='flex';\n  goTo('screen-today');\n  renderToday();\n  setInterval(tickClock, 1000*15);\n  tickClock();\n}\n\nwindow.addEventListener('load', ()=>{\n  load();\n  if(STATE.profile){ initMainApp(); } else { goTo('screen-welcome'); }\n\n  if('serviceWorker' in navigator){\n    navigator.serviceWorker.register('service-worker.js').catch(()=>{});\n    // Auto-reload page when a new SW version takes over — ensures users always\n    // get fresh app files after a Netlify deploy without clearing cache manually.\n    navigator.serviceWorker.addEventListener('controllerchange', () => {\n      window.location.reload();\n    });\n  }\n\n  // Fix: shrink sheets when keyboard appears so results stay visible\n  function handleViewportResize(){\n    const activeSheet = document.querySelector('.sheet-backdrop.active .sheet');\n    if(!activeSheet) return;\n    const vv = window.visualViewport;\n    if(!vv) return;\n    // Leave a little padding above keyboard\n    activeSheet.style.maxHeight = Math.floor(vv.height * 0.94) + 'px';\n  }\n  if(window.visualViewport){\n    window.visualViewport.addEventListener('resize', handleViewportResize);\n    window.visualViewport.addEventListener('scroll', handleViewportResize);\n  }\n\n  // When search input gains focus, scroll results into view after keyboard settles\n  document.getElementById('add-search').addEventListener('focus', ()=>{\n    setTimeout(()=>{\n      document.getElementById('add-search').scrollIntoView({behavior:'smooth', block:'start'});\n    }, 350);\n  });\n});\n"}, {"name": "enhancements.js", "code": "/* Daily Plate v1.1 enhancements */\nconst DP_VERSION='1.1';\nconst DP_SCHEMA_VERSION=4;\nconst dpOriginalLoad=load;\nconst dpOriginalSave=save;\nconst dpOriginalAllIngredients=allIngredients;\nconst dpOriginalConfirmAddEntry=confirmAddEntry;\nconst dpOriginalRenderToday=renderToday;\nconst dpOriginalRenderLog=renderLog;\nconst dpOriginalRenderProfile=renderProfileScreen;\nconst dpOriginalRenderIngredients=renderIngredientLibrary;\nconst dpOriginalOpenQty=openQtySheet;\nlet dpEdit=null;\n\nfunction dpId(prefix){return prefix+'_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,9)}\nfunction dpSlug(v){return String(v||'food').toLowerCase().normalize('NFKD').replace(/[\\u0300-\\u036f]/g,'').replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'').slice(0,60)}\nfunction dpBuiltinId(i){return i.id||'food_'+dpSlug(i.name)}\nfunction dpEscape(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]))}\nfunction dpMigrate(s){\n s=s&&typeof s==='object'?s:{};s.profile=s.profile||null;s.logs=s.logs||{};s.customIngredients=Array.isArray(s.customIngredients)?s.customIngredients:[];s.deletedBuiltins=Array.isArray(s.deletedBuiltins)?s.deletedBuiltins:[];\n s.favourites=Array.isArray(s.favourites)?s.favourites:[];s.recentIngredients=Array.isArray(s.recentIngredients)?s.recentIngredients:[];s.lastServings=s.lastServings||{};s.recipes=Array.isArray(s.recipes)?s.recipes:[];s.weights=Array.isArray(s.weights)?s.weights:[];s.settings=s.settings||{};\n s.deletedBuiltins=s.deletedBuiltins.map(id=>{if(/^b\\d+$/.test(id)){const i=INGREDIENTS[Number(id.slice(1))];return i?dpBuiltinId(i):id}return id});\n s.customIngredients.forEach(i=>{i.id=i.id||dpId('custom');i.basis=i.basis||(i.isLiquid?'100ml':'100g')});\n Object.entries(s.logs).forEach(([date,day])=>MEALS.forEach(m=>{day[m.key]=Array.isArray(day[m.key])?day[m.key]:[];day[m.key].forEach(e=>{e.id=e.id||dpId('entry');e.quantity=Number(e.quantity||e.grams)||0;e.grams=Number(e.grams||e.quantity)||0;if(!e.ingredientId){const n=String(e.name||'').replace(/\\s×\\d+(\\.\\d+)?$/,'');const i=[...s.customIngredients,...INGREDIENTS].find(x=>x.name===n);e.ingredientId=i?(i.id||dpBuiltinId(i)):null}e.createdAt=e.createdAt||new Date(date+'T12:00:00').toISOString();e.updatedAt=e.updatedAt||e.createdAt})}));\n if(s.profile&&!s.weights.length&&Number(s.profile.weight)>0)s.weights.push({id:dpId('weight'),date:todayKey(),value:Number(s.profile.weight)});\n s.schemaVersion=DP_SCHEMA_VERSION;s.sync=s.sync||{enabled:false,deviceId:dpId('device'),lastModified:new Date().toISOString()};return s;\n}\nload=function(){try{STATE=dpMigrate(JSON.parse(localStorage.getItem('dp_state')||'{}'))}catch(e){STATE=dpMigrate({})}};\nsave=function(){try{const old=localStorage.getItem('dp_state');if(old)localStorage.setItem('dp_recovery',old);STATE.schemaVersion=DP_SCHEMA_VERSION;STATE.sync=STATE.sync||{};STATE.sync.lastModified=new Date().toISOString();localStorage.setItem('dp_state',JSON.stringify(STATE))}catch(e){toast('Unable to save data')}};\nallIngredients=function(){const b=INGREDIENTS.map(i=>({...i,id:dpBuiltinId(i),basis:i.basis||(i.isLiquid?'100ml':'100g')})).filter(i=>!STATE.deletedBuiltins.includes(i.id));return [...STATE.customIngredients,...b]};\nfindIngredient=function(id){return allIngredients().find(i=>i.id===id)};\nfunction dpNutrition(e){const i=e.ingredientId?findIngredient(e.ingredientId):null;if(!i)return e;const x=(Number(e.quantity||e.grams)||0)/100;return {...e,cal:i.cal*x,p:i.p*x,c:i.c*x,f:i.f*x,sugar:(i.sugar||0)*x,fiber:(i.fiber||0)*x,sodium:(i.sodium||0)*x}}\nfunction dpTotals(k){const o={cal:0,p:0,c:0,f:0,sugar:0,fiber:0,sodium:0},d=getDayLog(k);MEALS.forEach(m=>(d[m.key]||[]).forEach(e=>{const n=dpNutrition(e);Object.keys(o).forEach(x=>o[x]+=Number(n[x])||0)}));return o}\n\nconfirmAddEntry=function(){const i=findIngredient(activeIngredientForQty);if(!i)return;const amount=qtyMode==='count'&&i.uw?qtyCount*i.uw:Number(document.getElementById('qty-grams').value);if(!(amount>0)){toast('Enter a valid amount');return}const x=amount/100,e={id:dpId('entry'),ingredientId:i.id,name:qtyMode==='count'&&i.uw?i.name+' ×'+qtyCount:i.name,quantity:amount,grams:Math.round(amount),unit:i.isLiquid?'ml':'g',cal:i.cal*x,p:i.p*x,c:i.c*x,f:i.f*x,sugar:(i.sugar||0)*x,fiber:(i.fiber||0)*x,sodium:(i.sodium||0)*x,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};const k=editingLogDate||todayKey();getDayLog(k)[activeMealKey].push(e);STATE.lastServings[i.id]={amount,mode:qtyMode,count:qtyCount};STATE.recentIngredients=[i.id,...STATE.recentIngredients.filter(x=>x!==i.id)].slice(0,12);save();closeSheet('sheet-qty');toast('Added');editingLogDate?renderLogDayDetail(k):renderToday()};\nopenQtySheet=function(id){dpOriginalOpenQty(id);const x=STATE.lastServings[id],i=findIngredient(id);if(x&&i){if(x.mode==='count'&&i.uw){qtyMode='count';qtyCount=x.count||1;document.getElementById('qty-count-num').textContent=qtyCount}else{switchQtyMode('grams');document.getElementById('qty-grams').value=x.amount}updateQtyPreview()}};\n\nrenderToday=function(){Object.values(STATE.logs||{}).forEach(d=>MEALS.forEach(m=>(d[m.key]||[]).forEach((e,n)=>d[m.key][n]=dpNutrition(e))));dpOriginalRenderToday();if(!STATE.profile)return;const t=dpTotals(todayKey()),target=calcCalorieTarget(STATE.profile),diff=target-t.cal;document.getElementById('cal-remaining-sub').textContent=diff>=0?Math.round(diff)+' remaining':Math.abs(Math.round(diff))+' over';if(STATE.profile.carbTarget)setPill('carb',t.c,STATE.profile.carbTarget);if(STATE.profile.fatTarget)setPill('fat',t.f,STATE.profile.fatTarget);const h=document.getElementById('dp-today-extra');if(h){const ids=[...STATE.favourites,...STATE.recentIngredients].filter((x,n,a)=>a.indexOf(x)===n).slice(0,6);h.innerHTML='<button class=\"btn ember\" onclick=\"dpQuickLog()\">＋ Log food</button><div class=\"micro-grid\"><div><b>'+Math.round(t.fiber)+'g</b><span>Fibre</span></div><div><b>'+Math.round(t.sugar)+'g</b><span>Sugar</span></div><div><b>'+Math.round(t.sodium)+'mg</b><span>Sodium</span></div></div><div class=\"section-title\">Quick add</div><div class=\"quick-chips\">'+(ids.map(id=>{const i=findIngredient(id);return i?'<button onclick=\"dpQuickAdd(\\''+i.id+'\\')\">'+dpEscape(i.name)+'</button>':''}).join('')||'<span class=\"empty-hint\">Recent and favourite foods appear here.</span>')+'</div>'}};\nfunction dpMealNow(){const h=new Date().getHours();return h<10?'breakfast':h<15?'lunch':h<20?'dinner':'snacks'}\nfunction dpQuickLog(){openAddSheet(dpMealNow(),'')}\nfunction dpQuickAdd(id){activeMealKey=dpMealNow();editingLogDate=null;openQtySheet(id)}\n\nfunction dpOpenEntry(date,meal,index){dpEdit={date,meal,index};const e=STATE.logs[date][meal][index],n=dpNutrition(e);document.getElementById('dp-edit-name').textContent=e.name;document.getElementById('dp-edit-amount').value=e.quantity||e.grams;document.getElementById('dp-edit-meal').value=meal;document.getElementById('dp-edit-summary').textContent=Math.round(n.cal)+' kcal · P '+Math.round(n.p)+'g · C '+Math.round(n.c)+'g · F '+Math.round(n.f)+'g';openSheet('sheet-dp-edit')}\nfunction dpSaveEntry(){const c=dpEdit,e=STATE.logs[c.date][c.meal][c.index],a=Number(document.getElementById('dp-edit-amount').value),m=document.getElementById('dp-edit-meal').value;if(!(a>0)){toast('Enter a valid amount');return}e.quantity=a;e.grams=Math.round(a);e.updatedAt=new Date().toISOString();const n=dpNutrition(e);STATE.logs[c.date][c.meal].splice(c.index,1);STATE.logs[c.date][m].push(n);save();closeSheet('sheet-dp-edit');c.date===todayKey()?renderToday():renderLogDayDetail(c.date);toast('Entry updated')}\nfunction dpDuplicateEntry(){const c=dpEdit,e=JSON.parse(JSON.stringify(STATE.logs[c.date][c.meal][c.index]));e.id=dpId('entry');STATE.logs[c.date][c.meal].push(e);save();closeSheet('sheet-dp-edit');c.date===todayKey()?renderToday():renderLogDayDetail(c.date);toast('Entry duplicated')}\nfunction dpDeleteEntry(){const c=dpEdit;STATE.logs[c.date][c.meal].splice(c.index,1);save();closeSheet('sheet-dp-edit');c.date===todayKey()?renderToday():renderLogDayDetail(c.date);toast('Entry deleted')}\nfunction dpWireEntries(){document.querySelectorAll('#meals-container .entry,#log-day-detail .entry').forEach(el=>{if(el.dataset.dpWired)return;el.dataset.dpWired='1';el.addEventListener('click',ev=>{if(ev.target.closest('.edel'))return;const card=el.closest('.meal-card'),container=card.parentElement,mealIndex=[...container.children].indexOf(card),entryIndex=[...el.parentElement.children].indexOf(el),date=container.id==='meals-container'?todayKey():viewingLogDate;dpOpenEntry(date,MEALS[mealIndex].key,entryIndex)})})}\nconst observer=new MutationObserver(dpWireEntries);\n\nrenderIngredientLibrary=function(){dpOriginalRenderIngredients();document.querySelectorAll('#ingredient-library .ing-row').forEach(r=>{const n=r.querySelector('.iname')?.textContent,i=allIngredients().find(x=>x.name===n);if(!i)return;const b=document.createElement('button');b.className='fav-btn';b.textContent=STATE.favourites.includes(i.id)?'★':'☆';b.onclick=e=>{e.stopPropagation();STATE.favourites=STATE.favourites.includes(i.id)?STATE.favourites.filter(x=>x!==i.id):[...STATE.favourites,i.id];save();renderIngredientLibrary()};r.appendChild(b)})};\n\nrenderLog=function(){dpOriginalRenderLog();const h=document.getElementById('dp-trends');if(!h)return;const days=[];for(let x=6;x>=0;x--){const d=new Date();d.setDate(d.getDate()-x);const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');days.push({k,...dpTotals(k)})}const logged=days.filter(x=>x.cal),avg=k=>logged.length?logged.reduce((a,x)=>a+x[k],0)/logged.length:0;h.innerHTML='<div class=\"card\"><h3>Nutrition trends</h3><div class=\"stat-grid\"><div class=\"stat-box\"><div class=\"v\">'+Math.round(avg('cal'))+'</div><div class=\"k\">Avg calories</div></div><div class=\"stat-box\"><div class=\"v\">'+Math.round(avg('p'))+'g</div><div class=\"k\">Avg protein</div></div></div><div class=\"spark-bars\">'+days.map(x=>'<i style=\"height:'+Math.max(3,Math.min(100,x.cal/calcCalorieTarget(STATE.profile)*100))+'%\"></i>').join('')+'</div></div>'};\nrenderProfileScreen=function(){dpOriginalRenderProfile();const h=document.getElementById('dp-profile-extra');if(!h)return;const p=STATE.profile;h.innerHTML='<div class=\"card\"><h3>Custom targets</h3><div class=\"row2\"><div><label>Carbs (g)</label><input id=\"dp-carb\" type=\"number\" value=\"'+(p.carbTarget||'')+'\"></div><div><label>Fat (g)</label><input id=\"dp-fat\" type=\"number\" value=\"'+(p.fatTarget||'')+'\"></div></div><button class=\"btn\" onclick=\"dpSaveTargets()\">Save targets</button></div><div class=\"card\"><h3>Weight history</h3><input id=\"dp-weight\" type=\"number\" step=\"0.1\" placeholder=\"Weight in kg\"><button class=\"btn top-gap\" onclick=\"dpAddWeight()\">Add today’s weight</button></div><div class=\"card\"><h3>App information</h3><p><b>Daily Plate v'+DP_VERSION+'</b><br><span class=\"helper\">Schema '+DP_SCHEMA_VERSION+' · Local-first · Sync-ready data model</span></p><button class=\"btn ghost\" onclick=\"dpExportCSV()\">Export logs as CSV</button></div>'};\nfunction dpSaveTargets(){STATE.profile.carbTarget=Number(document.getElementById('dp-carb').value)||null;STATE.profile.fatTarget=Number(document.getElementById('dp-fat').value)||null;save();renderToday();toast('Targets saved')}\nfunction dpAddWeight(){const v=Number(document.getElementById('dp-weight').value);if(!(v>20&&v<500)){toast('Enter a valid weight');return}STATE.weights=STATE.weights.filter(x=>x.date!==todayKey());STATE.weights.push({id:dpId('weight'),date:todayKey(),value:v});STATE.profile.weight=v;save();renderProfileScreen();toast('Weight recorded')}\nfunction dpExportCSV(){const rows=[['date','meal','food','amount','unit','calories','protein','carbs','fat']];Object.entries(STATE.logs).forEach(([d,day])=>MEALS.forEach(m=>(day[m.key]||[]).forEach(e=>{const n=dpNutrition(e);rows.push([d,m.name,e.name,e.quantity||e.grams,e.unit,n.cal,n.p,n.c,n.f])})));const csv=rows.map(r=>r.map(v=>'\"'+String(v).replace(/\"/g,'\"\"')+'\"').join(',')).join('\\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='daily-plate-v1.1-logs.csv';a.click();URL.revokeObjectURL(a.href)}\n\nfunction dpInit(){document.title='Daily Plate v'+DP_VERSION;const g=document.getElementById('today-greeting');if(g&&!document.getElementById('dp-version'))g.insertAdjacentHTML('afterend','<span id=\"dp-version\" class=\"version-badge\">v'+DP_VERSION+'</span>');document.querySelector('#screen-today .card')?.insertAdjacentHTML('afterend','<div id=\"dp-today-extra\"></div>');document.querySelector('#screen-log .day-strip')?.insertAdjacentHTML('afterend','<div id=\"dp-trends\"></div>');document.querySelector('#screen-profile .card:last-of-type')?.insertAdjacentHTML('beforebegin','<div id=\"dp-profile-extra\"></div>');document.getElementById('app').insertAdjacentHTML('beforeend','<div class=\"sheet-backdrop\" id=\"sheet-dp-edit\"><div class=\"sheet\"><div class=\"sheet-handle\"></div><div class=\"sheet-title\" id=\"dp-edit-name\">Edit entry</div><label>Amount (g/ml)</label><input id=\"dp-edit-amount\" type=\"number\"><label>Meal</label><select id=\"dp-edit-meal\">'+MEALS.map(m=>'<option value=\"'+m.key+'\">'+m.name+'</option>').join('')+'</select><p id=\"dp-edit-summary\" class=\"helper\"></p><button class=\"btn ember\" onclick=\"dpSaveEntry()\">Save changes</button><div class=\"row-actions\"><button class=\"btn ghost\" onclick=\"dpDuplicateEntry()\">Duplicate</button><button class=\"btn ghost danger\" onclick=\"dpDeleteEntry()\">Delete</button></div></div></div>');observer.observe(document.getElementById('app'),{subtree:true,childList:true});if(STATE.profile){renderToday();renderLog();renderProfileScreen()}dpWireEntries()}\nwindow.addEventListener('load',()=>setTimeout(dpInit,50));\n"}, {"name": "v13.js", "code": "/* Daily Plate v1.3 - dashboard and shared header */\nconst V13_VERSION='1.3';\nlet v13Edit=null;\nconst v13BaseSwitch=switchTab;\nconst v13BaseToday=renderToday;\nconst v13BaseLog=renderLog;\nconst v13BaseProfile=renderProfileScreen;\nconst v13BaseSaveIngredient=saveIngredientEditor;\nconst v13BaseDeleteIngredient=deleteIngredientEditor;\nconst v13BaseFindIngredient=findIngredient;\nconst v13BaseAllIngredients=allIngredients;\n\nfunction v13TabLabel(id){return ({'screen-home':'Home','screen-today':'Today','screen-log':'Log','screen-ingredients':'Ingredients','screen-profile':'Profile'})[id]||'Daily Plate';}\nfunction v13SetHeader(id){const el=document.getElementById('app-tab-name');if(el)el.textContent=v13TabLabel(id);}\nfunction v13Totals(key){const o={cal:0,p:0,c:0,f:0},day=STATE.logs[key];if(!day)return o;MEALS.forEach(m=>(day[m.key]||[]).forEach(e=>{const n=dpNutrition(e);o.cal+=Number(n.cal)||0;o.p+=Number(n.p)||0;o.c+=Number(n.c)||0;o.f+=Number(n.f)||0;}));return o;}\nfunction v13DateKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}\nfunction v13Days(count){const out=[];for(let i=count-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=v13DateKey(d);out.push({k,d,...v13Totals(k)});}return out;}\nfunction v13MacroTargets(){const cal=calcCalorieTarget(STATE.profile);return {cal,p:calcProteinTarget(STATE.profile),c:STATE.profile.carbTarget||Math.round(cal*.45/4),f:STATE.profile.fatTarget||Math.round(cal*.27/9)};}\nfunction v13Ring(label,value,target,color){const pct=target?Math.round(value/target*100):0,cap=Math.max(0,Math.min(100,pct));return `<div class=\"avg-tile\"><div class=\"avg-ring\" style=\"--ring:${cap};--ring-color:${color}\"><div><strong>${Math.round(value)}${label==='Calories'?'':'g'}</strong><small>${pct}%</small></div></div><span>${label}</span><em>Target ${Math.round(target)}${label==='Calories'?' kcal':'g'}</em></div>`;}\nfunction renderHome(){if(!STATE.profile)return;v13RefreshEntries();const days30=v13Days(30),logged=days30.filter(x=>x.cal>0),avg=k=>logged.length?logged.reduce((a,x)=>a+x[k],0)/logged.length:0,t=v13MacroTargets();document.getElementById('home-greeting').textContent='Hello, '+STATE.profile.name;document.getElementById('home-dashboard').innerHTML=`<div class=\"card overview-card\"><div class=\"card-heading-row\"><div><h3>30-Day Overview</h3><p>Swipe horizontally to view earlier days</p></div><span>${logged.length} logged</span></div><div class=\"overview-scroll\" id=\"overview-scroll\"><div class=\"overview-track\">${days30.map(x=>{const pct=t.cal?Math.min(120,x.cal/t.cal*100):0;return `<div class=\"overview-day\"><div class=\"overview-cal\">${x.cal?Math.round(x.cal):'—'}</div><div class=\"overview-bar-wrap\"><i class=\"${x.cal>t.cal?'over':''}\" style=\"height:${x.cal?Math.max(5,pct*.72):3}px\"></i></div><b>${x.d.toLocaleDateString(undefined,{weekday:'narrow'})}</b><small>${x.d.getDate()}</small></div>`;}).join('')}</div></div></div><div class=\"card\"><div class=\"card-heading-row\"><div><h3>30-Day Average</h3><p>Based on ${logged.length} logged day${logged.length===1?'':'s'}</p></div></div><div class=\"avg-ring-grid\">${v13Ring('Calories',avg('cal'),t.cal,'#E8643A')}${v13Ring('Protein',avg('p'),t.p,'#7FA37E')}${v13Ring('Carbs',avg('c'),t.c,'#C9A227')}${v13Ring('Fat',avg('f'),t.f,'#2F6F8F')}</div></div>`;requestAnimationFrame(()=>{const sc=document.getElementById('overview-scroll');if(sc)sc.scrollLeft=sc.scrollWidth;});}\n\nswitchTab=function(id){v13SetHeader(id);if(id==='screen-home'){goTo(id);document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===id));renderHome();}else v13BaseSwitch(id);};\ninitMainApp=function(){document.getElementById('tabbar').style.display='flex';goTo('screen-home');document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab==='screen-home'));v13SetHeader('screen-home');renderHome();setInterval(tickClock,15000);tickClock();};\n\nfunction v13RefreshEntries(){Object.values(STATE.logs||{}).forEach(d=>MEALS.forEach(m=>(d[m.key]||[]).forEach((e,n)=>d[m.key][n]=dpNutrition(e))));}\nrenderToday=function(){v13RefreshEntries();v13BaseToday();document.getElementById('today-greeting').textContent='';const extra=document.getElementById('dp-today-extra');if(extra){const ids=[...STATE.favourites,...STATE.recentIngredients].filter((x,n,a)=>a.indexOf(x)===n).slice(0,6);extra.innerHTML=`<div class=\"section-title\">Quick add</div><div class=\"quick-chips\">${ids.map(id=>{const i=findIngredient(id);return i&&!i.hidden?`<button onclick=\"v13Quick('${id}')\">${dpEscape(i.name)}</button>`:''}).join('')||'<span class=\"empty-hint\">Recent and favourite foods appear here.</span>'}</div>`;}};\nfunction v13Quick(id){activeIngredientForQty=id;openSheet('sheet-v13-meal');}\nfunction v13QuickContinue(){activeMealKey=document.getElementById('v13-meal').value;editingLogDate=null;closeSheet('sheet-v13-meal');openQtySheet(activeIngredientForQty);}\n\nfunction v13RenderLogDay(key){const host=document.getElementById('log-day-detail'),day=getDayLog(key),isToday=key===todayKey(),editable=key===tomorrowKey()||(key<todayKey()&&logEditMode);host.innerHTML=isToday?'<div class=\"log-readonly-notice\">Add using Today Tab</div>':'';MEALS.forEach(m=>{const entries=day[m.key]||[],card=document.createElement('div');card.className='card meal-card';card.innerHTML=`<div class=\"meal-head\"><div class=\"left\"><div class=\"meal-icon\">${m.icon}</div><div><div class=\"meal-name\">${m.name}</div><div class=\"meal-cals\">${Math.round(entries.reduce((a,e)=>a+dpNutrition(e).cal,0))} kcal</div></div></div>${editable?`<button class=\"add-btn\" onclick=\"openAddSheet('${m.key}','${key}')\">+</button>`:''}</div><div class=\"entry-list\">${entries.length?entries.map((raw,n)=>{const e=dpNutrition(raw);return `<div class=\"entry ${editable?'entry-editable':''}\" ${editable?`onclick=\"v13OpenEdit('${key}','${m.key}',${n})\"`:''}><div><div class=\"ename\">${dpEscape(e.name)}</div><div class=\"emeta\">${e.grams}${e.unit||'g'} · P${Math.round(e.p)} C${Math.round(e.c)} F${Math.round(e.f)}</div></div><div class=\"ecal\">${Math.round(e.cal)}</div></div>`;}).join(''):`<div class=\"empty-hint\">${editable?'Tap + to add food':'Nothing logged'}</div>`}</div>`;host.appendChild(card);});}\nrenderLogDayDetail=v13RenderLogDay;\nrenderWeekBar=function(){};\nrenderLog=function(){v13RefreshEntries();v13BaseLog();document.getElementById('dp-trends')?.remove();const p=document.getElementById('log-date-picker');if(p){p.max=tomorrowKey();p.value=viewingLogDate||todayKey();}v13RenderLogDay(viewingLogDate||todayKey());};\nfunction v13SelectDate(v){if(!v)return;if(v>tomorrowKey()){toast('Only tomorrow can be planned');return;}viewingLogDate=v;logEditMode=v===tomorrowKey();renderLog();}\nfunction v13OpenEdit(date,meal,index){if(date===todayKey()&&document.getElementById('screen-log').classList.contains('active'))return;v13Edit={date,meal,index};const e=STATE.logs[date][meal][index],i=findIngredient(e.ingredientId);document.getElementById('v13-edit-name').textContent=i?.name||e.name;document.getElementById('v13-amount').value=e.quantity||e.grams;const w=document.getElementById('v13-count-wrap');if(i?.uw&&!i.isLiquid){w.style.display='';document.getElementById('v13-count').value=e.count||Math.max(1,Math.round((e.quantity||e.grams)/i.uw));}else w.style.display='none';v13Preview();openSheet('sheet-v13-edit');}\nfunction v13Preview(){if(!v13Edit)return;const e=STATE.logs[v13Edit.date][v13Edit.meal][v13Edit.index],i=findIngredient(e.ingredientId),a=Number(document.getElementById('v13-amount').value)||0,x=a/100;document.getElementById('v13-summary').textContent=i?`${Math.round(i.cal*x)} kcal · P ${Math.round(i.p*x)}g · C ${Math.round(i.c*x)}g · F ${Math.round(i.f*x)}g`:'';}\nfunction v13CountChanged(){const e=STATE.logs[v13Edit.date][v13Edit.meal][v13Edit.index],i=findIngredient(e.ingredientId),c=Math.max(1,Number(document.getElementById('v13-count').value)||1);if(i?.uw){document.getElementById('v13-amount').value=Math.round(c*i.uw);v13Preview();}}\nfunction v13SaveEntry(){const c=v13Edit,e=STATE.logs[c.date][c.meal][c.index],i=findIngredient(e.ingredientId),a=Number(document.getElementById('v13-amount').value);if(!(a>0)){toast('Enter a valid amount');return;}e.quantity=a;e.grams=Math.round(a);e.count=i?.uw&&!i.isLiquid?Math.max(1,Number(document.getElementById('v13-count').value)||1):null;STATE.logs[c.date][c.meal][c.index]=dpNutrition(e);save();closeSheet('sheet-v13-edit');c.date===todayKey()?renderToday():renderLog();renderHome();toast('Entry updated');}\nfunction v13DeleteEntry(){const c=v13Edit;STATE.logs[c.date][c.meal].splice(c.index,1);save();closeSheet('sheet-v13-edit');c.date===todayKey()?renderToday():renderLog();renderHome();toast('Entry deleted');}\nfunction v13WireToday(){document.querySelectorAll('#meals-container .entry').forEach(el=>{if(el.dataset.v13)return;el.dataset.v13='1';el.addEventListener('click',ev=>{if(ev.target.closest('.edel'))return;const card=el.closest('.meal-card'),mi=[...document.getElementById('meals-container').children].indexOf(card),ei=[...el.parentElement.children].indexOf(el);v13OpenEdit(todayKey(),MEALS[mi].key,ei);});});}\nconst v13Observer=new MutationObserver(v13WireToday);\n\nfindIngredient=function(id){return v13BaseFindIngredient(id)||(STATE.archivedIngredients||[]).find(x=>x.id===id);};\nallIngredients=function(){return v13BaseAllIngredients().filter(x=>!x.hidden);};\nsaveIngredientEditor=function(){const id=activeEditingIngredientId;if(!id){v13BaseSaveIngredient();return;}const old=findIngredient(id),data={id,name:document.getElementById('ie-name').value.trim(),cat:document.getElementById('ie-cat').value.trim()||'Custom',cal:Number(document.getElementById('ie-cal').value)||0,p:Number(document.getElementById('ie-protein').value)||0,c:Number(document.getElementById('ie-carb').value)||0,f:Number(document.getElementById('ie-fat').value)||0,sugar:Number(document.getElementById('ie-sugar').value)||0,fiber:Number(document.getElementById('ie-fiber').value)||0,sodium:Number(document.getElementById('ie-sodium').value)||0,defaultServing:Number(document.getElementById('ie-default-serving').value)||100,isLiquid:isLiquidToggleOn,basis:isLiquidToggleOn?'100ml':'100g',uw:old?.uw,unit:old?.unit};const n=STATE.customIngredients.findIndex(x=>x.id===id);if(n>=0)STATE.customIngredients[n]=data;else STATE.customIngredients.push(data);STATE.deletedBuiltins=STATE.deletedBuiltins.filter(x=>x!==id);v13RefreshEntries();save();closeSheet('sheet-ing-edit');renderIngredientLibrary();renderToday();renderHome();if(document.getElementById('screen-log').classList.contains('active'))renderLog();toast('Ingredient updated throughout app');};\ndeleteIngredientEditor=function(){const id=activeEditingIngredientId;if(!id)return;STATE.archivedIngredients=STATE.archivedIngredients||[];const i=findIngredient(id);if(i&&!STATE.archivedIngredients.some(x=>x.id===id))STATE.archivedIngredients.push({...i,hidden:true});STATE.customIngredients=STATE.customIngredients.filter(x=>x.id!==id);if(!STATE.deletedBuiltins.includes(id))STATE.deletedBuiltins.push(id);save();closeSheet('sheet-ing-edit');renderIngredientLibrary();toast('Ingredient hidden from future use');};\nrenderProfileScreen=function(){v13BaseProfile();const h=document.getElementById('dp-profile-extra');if(h)h.innerHTML=`<div class=\"card\"><h3>App information</h3><p><b>Daily Plate v${V13_VERSION}</b><br><span class=\"helper\">Schema 5 · Local-first · Sync-ready data model</span></p></div>`;};\n\nfunction v13Init(){document.title='Daily Plate v1.3';document.querySelector('#dp-version')?.remove();document.querySelector('#dp-trends')?.remove();v13Observer.observe(document.getElementById('meals-container'),{childList:true,subtree:true});if(STATE.profile){v13SetHeader('screen-home');renderHome();renderToday();renderProfileScreen();}v13WireToday();}\nwindow.addEventListener('load',()=>setTimeout(v13Init,130));\n"}, {"name": "v14.js", "code": "/* Daily Plate v1.4 - streamlined headers and log editing */\nconst V14_VERSION='1.4';\nlet v14Edit=null;\nlet v14Undo=null;\nlet v14EditDayAuthorized=false;\nlet v14LastLogDate=null;\nconst v14BaseHome=renderHome;\nconst v14BaseToday=renderToday;\nconst v14BaseLog=renderLog;\nconst v14BaseProfile=renderProfileScreen;\n\nfunction v14Totals(key){const out={cal:0,p:0,c:0,f:0},day=STATE.logs[key];if(!day)return out;MEALS.forEach(m=>(day[m.key]||[]).forEach(raw=>{const e=dpNutrition(raw);out.cal+=Number(e.cal)||0;out.p+=Number(e.p)||0;out.c+=Number(e.c)||0;out.f+=Number(e.f)||0;}));return out;}\nfunction v14Days(count){const out=[];for(let i=count-1;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');out.push({k,d,...v14Totals(k)});}return out;}\nfunction v14Targets(){const cal=calcCalorieTarget(STATE.profile);return {cal,p:calcProteinTarget(STATE.profile),c:STATE.profile.carbTarget||Math.round(cal*.45/4),f:STATE.profile.fatTarget||Math.round(cal*.27/9)};}\nfunction v14Ring(label,value,target,color){const pct=target?Math.round(value/target*100):0,cap=Math.max(0,Math.min(100,pct));return `<div class=\"avg-tile\"><div class=\"avg-ring\" style=\"--ring:${cap};--ring-color:${color}\"><div><strong>${Math.round(value)}${label==='Calories'?'':'g'}</strong><small>${pct}%</small></div></div><span>${label}</span><em>Target ${Math.round(target)}${label==='Calories'?' kcal':'g'}</em></div>`;}\nrenderHome=function(){if(!STATE.profile)return;v13RefreshEntries();const days=v14Days(30),logged=days.filter(x=>x.cal>0),avg=k=>logged.length?logged.reduce((a,x)=>a+x[k],0)/logged.length:0,t=v14Targets();document.getElementById('home-greeting').textContent='Hello, '+STATE.profile.name;document.getElementById('home-dashboard').innerHTML=`<div class=\"card overview-card\"><h3>30 Days Calorie Count</h3><div class=\"overview-scroll\" id=\"overview-scroll\"><div class=\"overview-track\">${days.map(x=>{const pct=t.cal?Math.min(120,x.cal/t.cal*100):0;return `<div class=\"overview-day\"><div class=\"overview-cal\">${x.cal?Math.round(x.cal):'—'}</div><div class=\"overview-bar-wrap\"><i class=\"${x.cal>t.cal?'over':''}\" style=\"height:${x.cal?Math.max(5,pct*.72):3}px\"></i></div><b>${x.d.toLocaleDateString(undefined,{weekday:'narrow'})}</b><small>${x.d.getDate()}</small></div>`;}).join('')}</div></div></div><div class=\"card\"><h3>30 Day Macros Average</h3><div class=\"avg-ring-grid\">${v14Ring('Calories',avg('cal'),t.cal,'#E8643A')}${v14Ring('Protein',avg('p'),t.p,'#7FA37E')}${v14Ring('Carbs',avg('c'),t.c,'#C9A227')}${v14Ring('Fat',avg('f'),t.f,'#2F6F8F')}</div></div>`;requestAnimationFrame(()=>{const sc=document.getElementById('overview-scroll');if(sc)sc.scrollLeft=sc.scrollWidth;});};\n\nfunction v14OpenEdit(date,meal,index){if(document.getElementById('screen-log').classList.contains('active')&&!v14EditDayAuthorized)return;v14Edit={date,meal,index};const e=STATE.logs[date][meal][index],i=findIngredient(e.ingredientId);document.getElementById('v14-edit-name').textContent=i?.name||e.name;document.getElementById('v14-amount').value=e.quantity||e.grams;const wrap=document.getElementById('v14-count-wrap');if(i?.uw&&!i.isLiquid){wrap.style.display='';document.getElementById('v14-count').value=e.count||Math.max(1,Math.round((e.quantity||e.grams)/i.uw));}else wrap.style.display='none';v14Preview();openSheet('sheet-v14-edit');}\n// Route every legacy entry-tap handler to the v1.4 editor.\n// v1.1 and v1.3 attached addEventListener handlers before v1.4 loaded; those\n// handlers resolve these global function names at click time.\ndpOpenEntry=function(date,meal,index){v14OpenEdit(date,meal,index);};\nv13OpenEdit=function(date,meal,index){v14OpenEdit(date,meal,index);};\n\nfunction v14Preview(){if(!v14Edit)return;const e=STATE.logs[v14Edit.date][v14Edit.meal][v14Edit.index],i=findIngredient(e.ingredientId),amount=Number(document.getElementById('v14-amount').value)||0,x=amount/100;document.getElementById('v14-summary').textContent=i?`${Math.round(i.cal*x)} kcal · P ${Math.round(i.p*x)}g · C ${Math.round(i.c*x)}g · F ${Math.round(i.f*x)}g`:'';}\nfunction v14CountChanged(){const e=STATE.logs[v14Edit.date][v14Edit.meal][v14Edit.index],i=findIngredient(e.ingredientId),count=Math.max(1,Number(document.getElementById('v14-count').value)||1);if(i?.uw){document.getElementById('v14-amount').value=Math.round(count*i.uw);v14Preview();}}\nfunction v14SaveEntry(){const c=v14Edit,e=STATE.logs[c.date][c.meal][c.index],i=findIngredient(e.ingredientId),amount=Number(document.getElementById('v14-amount').value);if(!(amount>0)){toast('Enter a valid amount');return;}e.quantity=amount;e.grams=Math.round(amount);e.count=i?.uw&&!i.isLiquid?Math.max(1,Number(document.getElementById('v14-count').value)||1):null;e.updatedAt=new Date().toISOString();STATE.logs[c.date][c.meal][c.index]=dpNutrition(e);save();closeSheet('sheet-v14-edit');c.date===todayKey()?renderToday():renderLog();renderHome();toast('Entry updated');}\nfunction v14Delete(date,meal,index){const removed=STATE.logs[date][meal].splice(index,1)[0];v14Undo={date,meal,index,entry:removed};save();date===todayKey()?renderToday():renderLog();renderHome();const t=document.getElementById('toast');t.textContent='Deleted · Undo';t.classList.add('show','undo-ready');t.style.pointerEvents='auto';t.onclick=v14UndoDelete;clearTimeout(window.v14ToastTimer);window.v14ToastTimer=setTimeout(()=>{t.classList.remove('show','undo-ready');t.style.pointerEvents='none';t.onclick=null;v14Undo=null;},3500);}\nfunction v14UndoDelete(){if(!v14Undo)return;const u=v14Undo;STATE.logs[u.date][u.meal].splice(u.index,0,u.entry);save();u.date===todayKey()?renderToday():renderLog();renderHome();v14Undo=null;const t=document.getElementById('toast');t.style.pointerEvents='none';t.onclick=null;toast('Restored');}\n\nfunction v14LogSummary(key){const totals=v14Totals(key);return `<div class=\"log-daily-summary\"><div class=\"daily-calorie\"><strong>${Math.round(totals.cal)}</strong><span>kcal</span></div><div class=\"daily-macros\"><div class=\"sum-protein\"><b>${Math.round(totals.p)}g</b><span>Protein</span></div><div class=\"sum-carbs\"><b>${Math.round(totals.c)}g</b><span>Carbs</span></div><div class=\"sum-fat\"><b>${Math.round(totals.f)}g</b><span>Fat</span></div></div></div>`;}\nfunction v14RenderLogDay(key){const host=document.getElementById('log-day-detail'),day=getDayLog(key),isToday=key===todayKey(),editable=!isToday&&v14EditDayAuthorized;host.innerHTML=isToday?'<div class=\"log-readonly-notice\">Add using Today Tab</div>':'';MEALS.forEach(m=>{const entries=day[m.key]||[],card=document.createElement('div');card.className='card meal-card';card.innerHTML=`<div class=\"meal-head\"><div class=\"left\"><div class=\"meal-icon\">${m.icon}</div><div><div class=\"meal-name\">${m.name}</div><div class=\"meal-cals\">${Math.round(entries.reduce((a,e)=>a+dpNutrition(e).cal,0))} kcal</div></div></div>${editable?`<button class=\"add-btn\" onclick=\"openAddSheet('${m.key}','${key}')\">+</button>`:''}</div><div class=\"entry-list\">${entries.length?entries.map((raw,n)=>{const e=dpNutrition(raw);return `<div class=\"entry ${editable?'entry-editable':''}\" ${editable?`onclick=\"v14OpenEdit('${key}','${m.key}',${n})\"`:''}><div><div class=\"ename\">${dpEscape(e.name)}</div><div class=\"emeta\">${e.grams}${e.unit||'g'} · P${Math.round(e.p)} C${Math.round(e.c)} F${Math.round(e.f)}</div></div><div class=\"eright\"><div class=\"ecal\">${Math.round(e.cal)}</div>${editable?`<button class=\"edel\" onclick=\"event.stopPropagation();v14Delete('${key}','${m.key}',${n})\" aria-label=\"Delete\">✕</button>`:''}</div></div>`;}).join(''):`<div class=\"empty-hint\">${editable?'Tap + to add food':'Nothing logged'}</div>`}</div>`;host.appendChild(card);});}\nrenderLogDayDetail=v14RenderLogDay;\nrenderLog=function(){const requestedKey=viewingLogDate||todayKey();if(v14LastLogDate!==requestedKey){v14EditDayAuthorized=false;logEditMode=false;v14LastLogDate=requestedKey;}v13RefreshEntries();v14BaseLog();document.getElementById('dp-trends')?.remove();const key=viewingLogDate||todayKey(),picker=document.getElementById('log-date-picker');if(picker){picker.max=tomorrowKey();picker.value=key;}const title=document.getElementById('log-day-title');if(title){document.getElementById('log-daily-summary')?.remove();title.insertAdjacentHTML('afterend',`<div id=\"log-daily-summary\">${v14LogSummary(key)}</div>`);}const edit=document.getElementById('log-edit-btn');if(key===todayKey()){v14EditDayAuthorized=false;logEditMode=false;edit.style.display='none';}else{edit.style.display='';edit.classList.toggle('active',v14EditDayAuthorized);edit.innerHTML=v14EditDayAuthorized?'Done Editing':'Edit Day';}v14RenderLogDay(key);};\ntoggleLogEdit=function(){if((viewingLogDate||todayKey())===todayKey())return;v14EditDayAuthorized=!v14EditDayAuthorized;logEditMode=v14EditDayAuthorized;renderLog();};\nfunction v13SelectDate(v){if(!v)return;if(v>tomorrowKey()){toast('Only tomorrow can be planned');return;}viewingLogDate=v;v14EditDayAuthorized=false;logEditMode=false;v14LastLogDate=v;renderLog();}\n\nrenderToday=function(){v14BaseToday();v14WireToday();};\nfunction v14WireToday(){document.querySelectorAll('#meals-container .entry').forEach((el)=>{if(el.dataset.v14)return;el.dataset.v14='1';el.onclick=(ev)=>{if(ev.target.closest('.edel'))return;const card=el.closest('.meal-card'),mealIndex=[...document.getElementById('meals-container').children].indexOf(card),index=[...el.parentElement.children].indexOf(el);v14OpenEdit(todayKey(),MEALS[mealIndex].key,index);};const old=el.querySelector('.edel');if(old){const card=el.closest('.meal-card'),mealIndex=[...document.getElementById('meals-container').children].indexOf(card),index=[...el.parentElement.children].indexOf(el);old.setAttribute('onclick',`event.stopPropagation();v14Delete('${todayKey()}','${MEALS[mealIndex].key}',${index})`);}});}\nconst v14Observer=new MutationObserver(v14WireToday);\n\nrenderProfileScreen=function(){v14BaseProfile();const h=document.getElementById('dp-profile-extra');if(h)h.innerHTML=`<div class=\"card\"><h3>App information</h3><p><b>Daily Plate v${V14_VERSION}</b><br><span class=\"helper\">Schema 5 · Local-first · Sync-ready data model</span></p></div>`;};\nfunction v14Init(){document.title='Daily Plate v1.4';document.querySelector('.app-header')?.remove();document.querySelectorAll('.app-tab-name').forEach(x=>x.remove());document.querySelector('.add-ingredient-primary')?.remove();document.querySelector('#dp-version')?.remove();document.querySelector('#dp-trends')?.remove();document.getElementById('sheet-dp-edit')?.remove();document.getElementById('sheet-v13-edit')?.remove();v14Observer.observe(document.getElementById('meals-container'),{childList:true,subtree:true});if(STATE.profile){renderHome();renderToday();renderProfileScreen();}v14WireToday();}\nwindow.addEventListener('load',()=>setTimeout(v14Init,170));\n"}, {"name": "v17.js", "code": "/* Daily Plate v1.7 - monthly History calendar and serving labels */\nconst V17_VERSION='1.9',V17_KJ_PER_KCAL=4.184;\nlet v17IngredientEnergySource='kcal',v17CalendarMonth=null,v17DeferredInstallPrompt=null;\nconst v17BaseToday=renderToday,v17BaseIngredients=renderIngredientLibrary,v17BaseOpenIngredient=openIngredientEditor,v17BaseSaveIngredient=saveIngredientEditor,v17BaseProfile=renderProfileScreen,v17BaseNutrition=dpNutrition;\nfunction v17DateKey(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}\nfunction v17Round(v){return Math.round((Number(v)||0)*10)/10}\nfunction v17Set(id,v){const e=document.getElementById(id);if(e)e.value=v>0?v17Round(v):''}\nfunction v17SyncIngredientEnergy(source){v17IngredientEnergySource=source;if(source==='kj'){const j=Number(document.getElementById('ie-kj').value)||0;v17Set('ie-cal',j/V17_KJ_PER_KCAL)}else{const k=Number(document.getElementById('ie-cal').value)||0;v17Set('ie-kj',k*V17_KJ_PER_KCAL)}}\nfunction v17HasLog(key){const d=STATE.logs&&STATE.logs[key];return !!(d&&MEALS.some(m=>(d[m.key]||[]).length))}\nfunction v17ShiftMonth(delta){if(!v17CalendarMonth)v17CalendarMonth=new Date();v17CalendarMonth=new Date(v17CalendarMonth.getFullYear(),v17CalendarMonth.getMonth()+delta,1);renderLog()}\nfunction v17SelectCalendarDate(key){if(key>tomorrowKey())return;viewingLogDate=key;v14EditDayAuthorized=false;logEditMode=false;v14LastLogDate=key;const d=keyToDate(key);v17CalendarMonth=new Date(d.getFullYear(),d.getMonth(),1);renderLog()}\nfunction v17RenderCalendar(){\n const host=document.getElementById('day-strip');if(!host)return;\n const selected=viewingLogDate||todayKey(),selectedDate=keyToDate(selected);\n if(!v17CalendarMonth)v17CalendarMonth=new Date(selectedDate.getFullYear(),selectedDate.getMonth(),1);\n const y=v17CalendarMonth.getFullYear(),m=v17CalendarMonth.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),offset=(first.getDay()+6)%7;\n const labels=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];\n let cells='';for(let i=0;i<offset;i++)cells+='<div class=\"month-day blank\" aria-hidden=\"true\"></div>';\n for(let day=1;day<=days;day++){const d=new Date(y,m,day),key=v17DateKey(d),future=key>tomorrowKey(),today=key===todayKey(),tomorrow=key===tomorrowKey(),active=key===selected,logged=v17HasLog(key);cells+=`<button class=\"month-day${active?' active':''}${today?' today':''}${tomorrow?' tomorrow':''}${future?' disabled':''}\" ${future?'disabled':''} onclick=\"v17SelectCalendarDate('${key}')\" aria-label=\"${d.toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}\"><span>${day}</span>${logged?'<i class=\"log-dot\"></i>':''}</button>`}\n host.className='month-calendar-wrap';host.innerHTML=`<div class=\"month-nav\"><button onclick=\"v17ShiftMonth(-1)\" aria-label=\"Previous month\">‹</button><strong>${first.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</strong><button onclick=\"v17ShiftMonth(1)\" aria-label=\"Next month\">›</button></div><div class=\"month-weekdays\">${labels.map(x=>`<span>${x}</span>`).join('')}</div><div class=\"month-grid\">${cells}</div>`;\n}\nrenderLog=function(){\n const key=viewingLogDate||todayKey();if(v14LastLogDate!==key){v14EditDayAuthorized=false;logEditMode=false;v14LastLogDate=key}\n v13RefreshEntries();v17RenderCalendar();\n const d=keyToDate(key),isToday=key===todayKey(),isTomorrow=key===tomorrowKey();\n let title=fmtDateLong(key);if(isToday)title+=' (today)';else if(isTomorrow)title+=' (tomorrow)';else title+=' (closed)';\n const titleEl=document.getElementById('log-day-title');if(titleEl)titleEl.textContent=title;\n document.getElementById('log-daily-summary')?.remove();if(titleEl)titleEl.insertAdjacentHTML('afterend',`<div id=\"log-daily-summary\" class=\"log-daily-summary\">${v14LogSummary(key)}</div>`);\n const edit=document.getElementById('log-edit-btn');if(isToday){v14EditDayAuthorized=false;logEditMode=false;edit.style.display='none'}else{edit.style.display='';edit.classList.toggle('active',v14EditDayAuthorized);edit.innerHTML=v14EditDayAuthorized?'Done Editing':'Edit Day'}\n v17RenderLogDay(key);\n};\nfunction v17RenderLogDay(key){\n const host=document.getElementById('log-day-detail'),day=getDayLog(key),isToday=key===todayKey(),editable=!isToday&&v14EditDayAuthorized;host.innerHTML='';\n MEALS.forEach(m=>{const entries=day[m.key]||[],card=document.createElement('div');card.className='card meal-card';card.innerHTML=`<div class=\"meal-head\"><div class=\"left\"><div class=\"meal-icon\">${m.icon}</div><div><div class=\"meal-name\">${m.name}</div><div class=\"meal-cals\">${Math.round(entries.reduce((a,e)=>a+dpNutrition(e).cal,0))} kcal</div></div></div>${editable?`<button class=\"add-btn\" onclick=\"openAddSheet('${m.key}','${key}')\">+</button>`:''}</div><div class=\"entry-list\">${entries.length?entries.map((raw,n)=>{const e=dpNutrition(raw);return `<div class=\"entry ${editable?'entry-editable':''}\" ${editable?`onclick=\"v14OpenEdit('${key}','${m.key}',${n})\"`:''}><div><div class=\"ename\">${dpEscape(e.name)}</div><div class=\"emeta\">${e.grams}${e.unit||'g'} · P${Math.round(e.p)} C${Math.round(e.c)} F${Math.round(e.f)}</div></div><div class=\"eright\"><div class=\"ecal\">${Math.round(e.cal)}</div>${editable?`<button class=\"edel\" onclick=\"event.stopPropagation();v14Delete('${key}','${m.key}',${n})\">✕</button>`:''}</div></div>`}).join(''):`<div class=\"empty-hint\">${editable?'Tap + to add food':'Nothing logged'}</div>`}</div>`;host.appendChild(card)})\n}\nrenderLogDayDetail=v17RenderLogDay;\nfunction v17Progress(label,value,target,color,unit){const pct=target?Math.round(value/target*100):0,cap=Math.max(0,Math.min(100,pct));return `<div class=\"home-progress-row\"><div class=\"home-progress-head\"><span>${label}</span><b>${Math.round(value)}${unit} <small>/ ${Math.round(target)}${unit}</small></b></div><div class=\"home-progress-track\"><i style=\"width:${cap}%;background:${color}\"></i></div><div class=\"home-progress-pct\">${pct}% of target</div></div>`}\nrenderHome=function(){if(!STATE.profile)return;v13RefreshEntries();const days=v14Days(30),logged=days.filter(x=>x.cal>0),avg=k=>logged.length?logged.reduce((a,x)=>a+x[k],0)/logged.length:0,t=v14Targets();document.getElementById('home-greeting').textContent='Hello, '+STATE.profile.name;document.getElementById('home-dashboard').innerHTML=`<div class=\"card overview-card\"><h3>Calorie Count</h3><div class=\"overview-scroll\" id=\"overview-scroll\"><div class=\"overview-track\">${days.map(x=>{const pct=t.cal?Math.min(120,x.cal/t.cal*100):0;return `<div class=\"overview-day\"><div class=\"overview-cal\">${x.cal?Math.round(x.cal):'—'}</div><div class=\"overview-bar-wrap\"><i class=\"${pct>100?'over':''}\" style=\"height:${Math.max(3,pct*.7)}px\"></i></div><b>${x.d.toLocaleDateString(undefined,{weekday:'narrow'})}</b><small>${x.d.getDate()}</small></div>`}).join('')}</div></div></div><div class=\"card home-progress-card\"><h3>Macros Target</h3><p class=\"home-progress-note\">Based on ${logged.length} logged day${logged.length===1?'':'s'}</p>${v17Progress('Calories',avg('cal'),t.cal,'#E8643A',' kcal')}${v17Progress('Protein',avg('p'),t.p,'#7FA37E','g')}${v17Progress('Carbs',avg('c'),t.c,'#C9A227','g')}${v17Progress('Fat',avg('f'),t.f,'#2F6F8F','g')}</div>`;requestAnimationFrame(()=>{const s=document.getElementById('overview-scroll');if(s)s.scrollLeft=s.scrollWidth})};\nrenderToday=function(){v17BaseToday();const q=document.getElementById('dp-today-extra');if(q)q.innerHTML='';document.querySelectorAll('#screen-today .macro-pill').forEach(x=>x.classList.add('macro-capsule'))};\nrenderIngredientLibrary=function(){v17BaseIngredients();document.querySelectorAll('#ingredient-library .fav-btn').forEach(x=>x.remove())};\nopenIngredientEditor=function(id){v17BaseOpenIngredient(id);v17IngredientEnergySource='kcal';const ing=id?findIngredient(id):null,k=Number(document.getElementById('ie-cal').value)||0;v17Set('ie-kj',k*V17_KJ_PER_KCAL);document.getElementById('ie-serving-label').value=ing?.servingLabel||''};\nsaveIngredientEditor=function(){\n if(v17IngredientEnergySource==='kj'){const j=Number(document.getElementById('ie-kj').value)||0;document.getElementById('ie-cal').value=j?Math.round((j/V17_KJ_PER_KCAL)*100)/100:0}\n const id=activeEditingIngredientId,label=document.getElementById('ie-serving-label').value.trim();v17BaseSaveIngredient();\n const saved=id?findIngredient(id):STATE.customIngredients[STATE.customIngredients.length-1];if(saved){saved.servingLabel=label;saved.fiber=0;saved.sodium=0;if(label){saved.uw=Number(saved.defaultServing)||100;saved.unit=label}else{delete saved.uw;delete saved.unit}}\n STATE.customIngredients.forEach(i=>{i.fiber=0;i.sodium=0});Object.values(STATE.logs||{}).forEach(day=>MEALS.forEach(m=>(day[m.key]||[]).forEach(e=>{delete e.fiber;delete e.sodium})));save();\n};\ndpNutrition=function(e){const n=v17BaseNutrition(e);if(n){delete n.fiber;delete n.sodium}return n};\nconst v17BaseOpenQty=openQtySheet;\nopenQtySheet=function(id){v17BaseOpenQty(id);const ing=findIngredient(id),label=ing?.servingLabel?.trim(),wrap=document.getElementById('qty-serving-label-info')||document.createElement('div');wrap.id='qty-serving-label-info';wrap.className='serving-label-info';wrap.innerHTML=label?`<b>Serving option</b><span>1 ${dpEscape(label)} = ${Math.round(ing.defaultServing||100)}${ing.isLiquid?'ml':'g'}</span><small>Use the count controls or manually enter g/ml.</small>`:'';const count=document.getElementById('qty-count-mode');if(label&&ing.defaultServing){ing.uw=ing.defaultServing;ing.unit=label;qtyMode='count';qtyCount=Math.max(1,Number(STATE.lastServings?.[id]?.count)||1);document.getElementById('qty-count-num').textContent=qtyCount;document.getElementById('qty-count-mode').style.display='';document.getElementById('qty-gram-mode').style.display='none';document.getElementById('qty-count-unit').textContent=label;document.getElementById('qty-count-grams-hint').textContent='= '+Math.round(qtyCount*ing.defaultServing)+(ing.isLiquid?'ml':'g')}if(wrap.parentNode==null)document.getElementById('qty-ing-name').parentElement.parentElement.insertBefore(wrap,count);wrap.style.display=label?'':'none';updateQtyPreview()};\nrenderProfileScreen=function(){v17BaseProfile();const h=document.getElementById('dp-profile-extra');if(h)h.innerHTML=`<div class=\"card\"><h3>App information</h3><p><b>Daily Plate v${V17_VERSION}</b><br><span class=\"helper\">Schema 5 · Local-first · Installable PWA</span></p></div>`};\nfunction v17Migrate(){STATE.favourites=[];INGREDIENTS.forEach(i=>{delete i.fiber;delete i.sodium});STATE.customIngredients.forEach(i=>{i.fiber=0;i.sodium=0});Object.values(STATE.logs||{}).forEach(day=>MEALS.forEach(m=>(day[m.key]||[]).forEach(e=>{delete e.fiber;delete e.sodium})));save()}\nfunction v17Init(){document.title='Daily Plate v1.9';v17Migrate();document.querySelectorAll('.fav-btn').forEach(x=>x.remove());if(STATE.profile){renderHome();renderToday();renderIngredientLibrary();renderProfileScreen();renderLog()}}\nwindow.addEventListener('beforeinstallprompt',e=>{e.preventDefault();v17DeferredInstallPrompt=e});\nwindow.addEventListener('load',()=>setTimeout(v17Init,250));\n"}, {"name": "v20.js", "code": "/* Daily Plate v2.0 - average calories and swipeable macro targets */\nconst V20_VERSION='2.1';\nlet v20MacroSlide=0;\n\nfunction v20RingColour(percent,totalLogged){\n  if(totalLogged===0)return '#A7AEA9';\n  if(percent>=100)return '#31D158';\n  if(percent>=80)return '#FFD60A';\n  return '#FF3B30';\n}\nfunction v20MacroStats(days,key,target,stayUnder=false){\n  const logged=days.filter(x=>x.cal>0);\n  const met=logged.filter(x=>stayUnder?(Number(x[key])||0)<=target:(Number(x[key])||0)>=target).length;\n  const percent=logged.length?Math.round(met/logged.length*100):0;\n  return {met,total:logged.length,percent,colour:v20RingColour(percent,logged.length)};\n}\nfunction v20MacroSlideMarkup(name,stats,index){\n  return `<section class=\"macro-swipe-slide\" data-slide=\"${index}\" aria-label=\"${name} target\"><div class=\"macro-target-name\">${name}</div><div class=\"macro-target-ring\" style=\"--macro-percent:${Math.min(100,stats.percent)};--macro-colour:${stats.colour}\"><div><strong>${stats.percent}%</strong></div></div><div class=\"macro-target-days\"><b>${stats.met} of ${stats.total} days</b><span>Target met</span></div></section>`;\n}\nfunction v20GoToMacro(index){\n  const viewport=document.getElementById('macro-swipe-viewport');\n  if(!viewport)return;\n  v20MacroSlide=Math.max(0,Math.min(2,index));\n  viewport.scrollTo({left:viewport.clientWidth*v20MacroSlide,behavior:'smooth'});\n  v20UpdateDots(v20MacroSlide);\n}\nfunction v20UpdateDots(index){\n  document.querySelectorAll('.macro-page-dot').forEach((dot,i)=>dot.classList.toggle('active',i===index));\n}\nfunction v20MacroScrolled(){\n  const viewport=document.getElementById('macro-swipe-viewport');\n  if(!viewport||!viewport.clientWidth)return;\n  v20MacroSlide=Math.max(0,Math.min(2,Math.round(viewport.scrollLeft/viewport.clientWidth)));\n  v20UpdateDots(v20MacroSlide);\n}\nfunction renderHome(){\n  if(!STATE.profile)return;\n  v13RefreshEntries();\n  const days=v14Days(30),logged=days.filter(x=>x.cal>0),averageCalories=logged.length?logged.reduce((sum,x)=>sum+x.cal,0)/logged.length:0,targets=v14Targets();\n  const protein=v20MacroStats(days,'p',targets.p),carbs=v20MacroStats(days,'c',targets.c),fat=v20MacroStats(days,'f',targets.f,true);\n  document.getElementById('home-greeting').textContent='Hello, '+STATE.profile.name;\n  document.getElementById('home-dashboard').innerHTML=`<div class=\"card overview-card\"><h3>Calorie Count</h3><div class=\"overview-scroll\" id=\"overview-scroll\"><div class=\"overview-track\">${days.map(x=>{const pct=targets.cal?Math.min(120,x.cal/targets.cal*100):0;return `<div class=\"overview-day\"><div class=\"overview-cal\">${x.cal?Math.round(x.cal):'—'}</div><div class=\"overview-bar-wrap\"><i class=\"${pct>100?'over':''}\" style=\"height:${Math.max(3,pct*.7)}px\"></i></div><b>${x.d.toLocaleDateString(undefined,{weekday:'narrow'})}</b><small>${x.d.getDate()}</small></div>`}).join('')}</div></div></div><div class=\"home-target-pair\"><div class=\"card home-half-card calorie-average-card\"><h3>30 Day Average</h3><div class=\"average-calorie-value\"><svg class=\"average-fire-icon\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M13.4 2.2c.5 3.2-1 4.6-2.3 6-1.1 1.2-2.1 2.4-1.8 4.4.1.7.5 1.4 1.2 1.9-.1-1.6.7-2.8 1.8-3.9.2 2.5 2.6 3.3 2.6 6 0 2.2-1.7 4-4.2 4-3.1 0-5.4-2.2-5.4-5.2 0-3.9 2.8-6 5.1-8.3 1.3-1.3 2.4-2.7 3-4.9Z\" fill=\"currentColor\"/><path d=\"M15.2 9.2c2.1 1.9 3.5 4 3.5 6.5 0 3.4-2.7 6.1-6.4 6.1 1.8-.9 2.8-2.6 2.8-4.6 0-2.1-1.2-3.3-2.1-4.4.9-.9 1.7-2 2.2-3.6Z\" fill=\"currentColor\" opacity=\".72\"/></svg><strong>${Math.round(averageCalories)}</strong><span>kcal</span></div></div><div class=\"card home-half-card macro-targets-card\"><h3>Macro Targets</h3><div class=\"macro-swipe-viewport\" id=\"macro-swipe-viewport\" onscroll=\"v20MacroScrolled()\"><div class=\"macro-swipe-track\">${v20MacroSlideMarkup('Protein',protein,0)}${v20MacroSlideMarkup('Carbs',carbs,1)}${v20MacroSlideMarkup('Fat',fat,2)}</div></div><div class=\"macro-page-dots\" aria-label=\"Macro slides\"><button class=\"macro-page-dot active\" onclick=\"v20GoToMacro(0)\" aria-label=\"Protein\"></button><button class=\"macro-page-dot\" onclick=\"v20GoToMacro(1)\" aria-label=\"Carbs\"></button><button class=\"macro-page-dot\" onclick=\"v20GoToMacro(2)\" aria-label=\"Fat\"></button></div></div></div>`;\n  requestAnimationFrame(()=>{const overview=document.getElementById('overview-scroll');if(overview)overview.scrollLeft=overview.scrollWidth;const macro=document.getElementById('macro-swipe-viewport');if(macro)macro.scrollLeft=macro.clientWidth*v20MacroSlide;});\n}\nconst v20BaseProfile=renderProfileScreen;\nrenderProfileScreen=function(){\n  v20BaseProfile();\n  const h=document.getElementById('dp-profile-extra');\n  if(h)h.innerHTML=`<div class=\"card\"><h3>App information</h3><p><b>Daily Plate v${V20_VERSION}</b><br><span class=\"helper\">Schema 5 · Local-first · Installable PWA</span></p></div>`;\n};\nfunction v20Init(){document.title='Daily Plate v2.1';if(STATE.profile){renderHome();renderProfileScreen();}}\nwindow.addEventListener('load',()=>setTimeout(v20Init,360));\n"}, {"name": "v22.js", "code": "/* Daily Plate v2.5 - consolidated single-file architecture */\nconst V22_VERSION='2.5';\nlet v22ProfileDetailsOpen=false;\nlet v22EditCard=null;\nlet v22EditBody=null;\n\nfunction v22SetEditDetails(open){\n  if(!v22EditCard||!v22EditBody)return;\n  v22ProfileDetailsOpen=!!open;\n  v22EditCard.classList.toggle('profile-edit-open',v22ProfileDetailsOpen);\n  v22EditBody.hidden=!v22ProfileDetailsOpen;\n  const trigger=v22EditCard.querySelector('.profile-edit-toggle');\n  if(trigger)trigger.setAttribute('aria-expanded',String(v22ProfileDetailsOpen));\n}\nfunction v22ToggleEditDetails(){v22SetEditDetails(!v22ProfileDetailsOpen);}\nfunction v22PrepareProfileCard(){\n  const profile=document.getElementById('screen-profile');\n  if(!profile)return;\n  const heading=[...profile.querySelectorAll('.card h3')].find(x=>x.textContent.trim().toLowerCase()==='edit details');\n  if(!heading)return;\n  const card=heading.closest('.card');\n  if(!card)return;\n  if(card.dataset.collapsibleReady==='1'){v22EditCard=card;v22EditBody=card.querySelector('.profile-edit-body');v22SetEditDetails(v22ProfileDetailsOpen);return;}\n  card.dataset.collapsibleReady='1';\n  const children=[...card.childNodes];\n  const body=document.createElement('div');body.className='profile-edit-body';body.hidden=true;\n  children.forEach(node=>{if(node!==heading)body.appendChild(node)});\n  const toggle=document.createElement('button');\n  toggle.type='button';toggle.className='profile-edit-toggle';toggle.setAttribute('aria-expanded','false');toggle.onclick=v22ToggleEditDetails;\n  toggle.innerHTML='<span>Edit Details</span><svg class=\"profile-edit-chevron\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m6 9 6 6 6-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>';\n  heading.remove();card.prepend(toggle);card.appendChild(body);v22EditCard=card;v22EditBody=body;v22SetEditDetails(false);\n}\nconst v22BaseRenderProfile=renderProfileScreen;\nrenderProfileScreen=function(){v22BaseRenderProfile();v22PrepareProfileCard();};\nconst v22BaseSaveProfile=saveProfileEdits;\nsaveProfileEdits=function(){v22BaseSaveProfile();v22PrepareProfileCard();v22SetEditDetails(false);};\nfunction v22Init(){\n  document.title='Daily Plate v2.5';\n  v22PrepareProfileCard();\n  if(STATE.profile)renderProfileScreen();\n  const h=document.getElementById('dp-profile-extra');\n  if(h)h.innerHTML='<div class=\"card\"><h3>App information</h3><p><b>Daily Plate v'+V22_VERSION+'</b><br><span class=\"helper\">Schema 5 · Local-first · Installable PWA</span></p></div>';\n}\nwindow.addEventListener('load',()=>setTimeout(v22Init,420));\n"}, {"name": "v24.js", "code": "/* Daily Plate v2.4 - ingredient precision, keyboard-safe editor, Diet Guru */\nconst V24_VERSION='2.5';\nfunction v24FormatCalories(value){\n  const n=Number(value)||0;\n  return n.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:2});\n}\nconst v24BaseRenderIngredientLibrary=renderIngredientLibrary;\nrenderIngredientLibrary=function(){\n  v24BaseRenderIngredientLibrary();\n  document.querySelectorAll('#ingredient-library .ing-row').forEach(row=>{\n    const name=row.querySelector('.iname')?.textContent;\n    const ing=allIngredients().find(item=>item.name===name);\n    const cal=row.querySelector('.ical');\n    if(ing&&cal)cal.textContent=v24FormatCalories(ing.cal)+' kcal';\n  });\n};\nconst v24BaseOpenIngredientEditor=openIngredientEditor;\nopenIngredientEditor=function(id){\n  v24BaseOpenIngredientEditor(id);\n  const cal=document.getElementById('ie-cal');\n  if(cal&&cal.value!=='')cal.value=v24FormatCalories(cal.value);\n  const sheet=document.querySelector('#sheet-ing-edit .sheet');\n  if(sheet)sheet.scrollTop=0;\n  requestAnimationFrame(()=>document.getElementById('ie-name')?.scrollIntoView({block:'nearest'}));\n};\nfunction v24KeepEditorFieldVisible(){\n  const backdrop=document.getElementById('sheet-ing-edit');\n  if(!backdrop?.classList.contains('active'))return;\n  const active=document.activeElement;\n  const target=active&&backdrop.contains(active)?active:document.getElementById('ie-name');\n  setTimeout(()=>target?.scrollIntoView({behavior:'smooth',block:'center'}),180);\n}\ndocument.addEventListener('visibilitychange',()=>{if(!document.hidden)v24KeepEditorFieldVisible()});\nwindow.addEventListener('focus',v24KeepEditorFieldVisible);\nif(window.visualViewport)window.visualViewport.addEventListener('resize',v24KeepEditorFieldVisible);\ndocument.addEventListener('focusin',e=>{if(e.target.closest?.('#sheet-ing-edit'))v24KeepEditorFieldVisible()});\n\nfunction v24MealCalories(day,mealKey){\n  return (day?.[mealKey]||[]).reduce((sum,entry)=>sum+(Number(dpNutrition(entry).cal)||0),0);\n}\nfunction v24DietGuruData(){\n  const target=calcCalorieTarget(STATE.profile);\n  const definitions=[\n    {key:'breakfast',name:'Breakfast',share:.20,icon:'sun'},\n    {key:'lunch',name:'Lunch',share:.35,icon:'bowl'},\n    {key:'snacks',name:'Snacks',share:.10,icon:'apple'},\n    {key:'dinner',name:'Dinner',share:.35,icon:'moon'}\n  ];\n  const days=v14Days(30).filter(item=>item.cal>0);\n  if(!days.length)return {empty:true};\n  const stats=definitions.map(def=>{\n    const requirement=target*def.share;\n    const amounts=days.map(item=>v24MealCalories(STATE.logs[item.k],def.key));\n    const met=amounts.filter(value=>value>=requirement).length;\n    const average=amounts.reduce((a,b)=>a+b,0)/days.length;\n    return {...def,requirement,met,average,shortfall:Math.max(0,requirement-average)};\n  });\n  stats.sort((a,b)=>a.met-b.met||b.shortfall-a.shortfall);\n  return {empty:false,days:days.length,meal:stats[0]};\n}\nfunction v24GuruIcon(name){\n  const icons={\n    sun:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"12\" r=\"4\"/><path d=\"M12 2v2M12 20v2M4.93 4.93l1.42 1.42M17.65 17.65l1.42 1.42M2 12h2M20 12h2M4.93 19.07l1.42-1.42M17.65 6.35l1.42-1.42\"/></svg>',\n    bowl:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 11h16a8 8 0 0 1-16 0Z\"/><path d=\"M8 4c0 2 2 2 2 4M13 3c0 2 2 2 2 5\"/></svg>',\n    apple:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 7c-2-3-7-2-8 3-1 6 4 11 8 11s9-5 8-11c-1-5-6-6-8-3Z\"/><path d=\"M12 7c0-3 2-5 5-5M12 5c-2 0-3-1-4-2\"/></svg>',\n    moon:'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 15.5A9 9 0 0 1 8.5 4 9 9 0 1 0 20 15.5Z\"/></svg>'\n  };\n  return icons[name]||icons.bowl;\n}\nfunction v24RenderDietGuru(){\n  const host=document.getElementById('home-dashboard');\n  if(!host)return;\n  host.querySelector('.diet-guru-card')?.remove();\n  const data=v24DietGuruData();\n  const card=document.createElement('div');\n  card.className='card diet-guru-card';\n  if(data.empty){\n    card.innerHTML='<div class=\"guru-heading\"><span class=\"guru-main-icon\">'+v24GuruIcon('bowl')+'</span><h3>Diet Guru Feedback</h3></div><p class=\"guru-message\">Log your meals to receive personalised 30-day feedback.</p><div class=\"guru-meta\">Waiting for your first logged day</div>';\n  }else{\n    const meal=data.meal;\n    const add=Math.round(meal.shortfall);\n    const message=add>0?'Consume more calories during your '+meal.name+'. Add <strong>'+add+' more calories</strong> to your daily '+meal.name.toLowerCase()+'.':'Your '+meal.name+' target is being met. Keep your meal pattern consistent.';\n    card.innerHTML='<div class=\"guru-heading\"><span class=\"guru-main-icon\">'+v24GuruIcon(meal.icon)+'</span><div><h3>Diet Guru Feedback</h3><span class=\"guru-kicker\">30-day meal insight</span></div></div><p class=\"guru-message\">'+message+'</p><div class=\"guru-stats\"><div><b>'+meal.met+' of '+data.days+'</b><span>target-met days</span></div><div><b>'+Math.round(meal.requirement)+' kcal</b><span>'+meal.name+' target</span></div></div>';\n  }\n  host.appendChild(card);\n}\nconst v24BaseRenderHome=renderHome;\nrenderHome=function(){v24BaseRenderHome();v24RenderDietGuru();};\nfunction v24UpdateAppInformation(){\n  const host=document.getElementById('dp-profile-extra');\n  if(host)host.innerHTML='<div class=\"card\"><h3>App information</h3><p><b>Daily Plate v'+V24_VERSION+'</b><br><span class=\"helper\">Schema 5 · Local-first · Installable PWA</span></p></div>';\n}\nconst v25BaseRenderProfile=renderProfileScreen;\nrenderProfileScreen=function(){v25BaseRenderProfile();v24UpdateAppInformation();};\nfunction v24Init(){\n  document.title='Daily Plate v'+V24_VERSION;\n  if(STATE.profile){renderHome();renderIngredientLibrary();renderProfileScreen();}\n}\nwindow.addEventListener('load',()=>setTimeout(v24Init,500));\n"}];
  for (const layer of layers) {
    const script = document.createElement('script');
    script.dataset.dailyPlateLayer = layer.name;
    script.textContent = layer.code + '\n//# sourceURL=daily-plate/' + layer.name;
    document.head.appendChild(script);
    script.remove();
  }
})();
